    "stem": "Se trata de una mujer de 21 años, sin antecedentes de importancia, que acude por lesiones dérmicas en la cara. Usted encuentra comedones abundantes y algunas pápulas eritematosas, algo dolorosas, diseminadas en frente, nariz, mejillas. En estas condiciones, junto con recomendaciones higiénicas, podrían indicarse algunos fármacos. ¿Cuál NO está indicado?",
