    "stem": "Un paciente varón de 72 años con antecedentes de alcoholismo crónico y cirrosis. Acude a emergencias por decaimiento, fiebre y dolor abdominal de 2 días de evolución. Al examen físico, lo relevante es la temperatura de 38.8 grados centígrados y frecuencia cardiaca 100 lpm (latidos por minuto) y presencia de ascitis, con dolor difuso a la palpación abdominal y peritonismo. La tomografía descarta compromiso visceral abdominal. La punción peritoneal reporta líquido con 300 polimorfonucleares por microlitro. Entre los siguientes gérmenes. ¿Cuál NO está implicado habitualmente en la etiología de este cuadro?",
