    "stem": "En relación al asma bronquial. Seleccione el enunciado correcto.",
    "options": [
      "El Asma es una patología multifactorial y poligénica. Hasta la actualidad se han identificado aproximadamente 100 genes relacionados con el desarrollo de esta patología.",
      "La siguiente sintomatología clínica no aumenta la probabilidad de Asma: tos, sibilancias, dificultad respiratoria y opresión torácica especialmente; ni los cuadros infecciosos de las vías respiratorias altas, tampoco empeora con el ejercicio, ni al contacto con mascotas.",
