  {
    "id": "html-126",
    "subject": "Banco general de medicina",
    "stem": "Paciente femenina de 10 meses de edad es traída por su madre debido a que manifiesta rechazo parcial del alimento, irritabilidad + alza térmica por tres ocasiones. La madre refiere que la niña ha presentado pielonefritis por 2 ocasiones anteriormente. Al examen físico Usted, corrobora lo dicho por la madre y al presentar alza térmica de 39°C sin foco infeccioso específico, solicita un urocultivo que muestra positividad. Corroborando así su diagnóstico de pielonefritis aguda. Con respecto al tratamiento y exámenes complementarios. ¿Qué opción de las siguientes no recomienda?",
    "options": [
      "Se recomienda por las infecciones recurrentes de la paciente realizar una ecografía renal más una cistouretrografía miccional; este abordaje identifica por excelencia alteraciones como cicatrices renales.",
      "Es preferible un ciclo de 7-14 días de antibióticos de amplio espectro que puedan alcanzar unas concentraciones tisulares adecuadas. Es preferible el tratamiento parenteral con ceftriaxona (50-75 mg/kg/24 h, sin superar los 2 g), cefotaxima (100 mg/kg/24 h) o ampicilina (100 mg/ kg/24 h) más un aminoglucósido como gentamicina (3-5 mg/kg/24 h en 1-3 dosis).",
      "Debe tenerse en cuenta la posible ototoxicidad y nefrotoxicidad de los aminoglucósidos, y se deben controlar las concentraciones séricas de creatinina y gentamicina antes del tratamiento y diariamente a lo largo de éste.",
      "Se recomienda realizar por las infecciones recurrentes una gammagrafía con DMSA; este abordaje identifica por excelencia alteraciones como cicatrices renales, las áreas involucradas del riñón son hipocaptantes y el riñón se mostrará agrandado."
    ],
