  {
    "id": "html-128",
    "subject": "Banco general de medicina",
    "stem": "El déficit de hierro es el trastorno nutricional más extendido y común en el mundo. Se estima que el 30% de la población global sufre anemia ferropénica y la mayor parte de los afectados viven en países en vías de desarrollo. Una vez recalcada la importancia de la anemia por déficit de hierro, escoja el enunciado verdadero:",
    "options": [
      "El diagnóstico de anemia por deficiencia de hierro se efectuará a través de la biometría hemática y el perfil de hierro, en donde se puede encontrar: hemoglobina disminuida, VCM disminuido, amplitud de distribución eritrocitaria elevada, ferritina sérica disminuida, captación total fija de hierro elevada.",
      "El recién nacido a término posee 5gr de hierro al igual que el adulto, por lo que, no es necesaria la alimentación rica en hierro en los primeros 15 años de vida.",
      "En el recién nacido a término la sección precoz del cordón umbilical <30 segundos no influye en el riesgo de déficit de hierro ni en las concentraciones de hemoglobina durante los 2 a 3 primeros meses de vida.",
      "La mayor parte de los niños con déficit de hierro se encuentran sintomáticos y son identificados por evaluación clínica. El signo que tarda en aparecer y menos frecuente es la palidez y se genera cuando la hemoglobina desciende de 4 g/dl"
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 128 · pág. 48",
    "fixedOrder": false
  },
  {
    "id": "html-129",
    "subject": "Banco general de medicina",
    "stem": "Paciente masculino de 4 años acude por presentar un cuadro de diarrea por cuatro ocasiones en las últimas 12 horas, las diarreas se caracterizan por ser mucosanguinolentas, poco voluminosas y con pujo, asociadas a fiebre de 39 °C. Al examen físico se halla un niño hidratado, con dolor abdominal a nivel de mesogastrio + alza térmica de 38.5 °C, abdomen levemente distendido. Usted diagnostica al niño de una enfermedad diarreica aguda y tiene la sospecha diagnóstica de que se trata de un mecanismo enteroinvasivo o inflamatorio. De los siguientes enunciados en relación al mecanismo mencionado. ¿Cuál es el correcto?",
    "options": [
      "Los principales agentes responsables del mecanismo enteroinvasivo o inflamatorio son la salmonella, shigella, E. coli enteroinvasiva, campylobacter, yersinia, bacilo cereus, vibrio parahaemolyticus, entamoeba histolyitica.",
      "En el mecanismo enteroinvasivo los gérmenes se adhieren a la mucosa intestinal a través de pilis y elaboran toxinas que generan la producción de cloro y un bloqueo de la absorción de sodio y de agua; se afecta principalmente el intestino delgado por lo que las diarreas son líquidas y abundantes.",
