    "stem": "Niño de 9 años es traído al departamento de emergencia debido a dificultad para respirar. El paciente estuvo en una reunión familiar toda la mañana. Veinte minutos después del almuerzo, desarrolló sibilancias y dificultad para respirar por lo que una ambulancia fue llamada. No ha tenido fiebre o infecciones recientes. El paciente tiene historial de eczema, alergia a los camarones y esta al día en sus vacunas. Al llegar al centro de salud, su temperatura es 37 °C, tensión arterial 70/50 mm Hg, pulso 140 /min, y respiraciones 30/min; su oximetría de pulso 89 % al aire ambiente. El examen físico revela un paciente ansioso, con incremento del trabajo respiratorio y sibilancias difusas en la auscultación. Las membranas mucosas parecen normales, y ningún exantema es visible. ¿Cuál es el mejor tratamiento inicial para este paciente?",
