    "stem": "Recién nacido hijo de madre diabética, primigesta, producto de cesárea de emergencia por preeclampsia, líquido claro con escasos grumos, con un tiempo de gestación de 37 semanas por FUM. Apgar 8 – 9 no requiere medidas de reanimación al nacimiento. A los 5 minutos de vida se aprecia presenta quejido audible, tiraje intercostal leve y aleteo nasal leve, se ausculta con buena entrada de aire se cataloga con dificultad respiratoria con un puntaje de Silverman de 3 puntos. Se traslada a neonatología y se coloca oxígeno por casco cefálico (hood) a 5 litros/min. Evolutivamente incremento de dificultad respiratoria con retracciones marcadas, y requiere inicio de ventilación mecánica no invasiva modalidad CPAP nasal, evolutivamente empeoramiento clínico hasta el tercer día donde comienza a mejorar progresivamente, desconectándose de ventilación mecánica no invasiva al quinto día de vida. ¿Cuál es el diagnóstico más probable de este recién nacido?",
