  {
    "id": "html-209",
    "subject": "Banco general de medicina",
    "stem": "La Desnutrición infantil es una enfermedad sistémica, a veces irreversible en el menor de 2 años y que tiene varias formas clínicas, por restricción de proteínas, calorías o ambas, lo que produce alteraciones fisiopatológicas que incluyen, aumento de estrés oxidativo, infecciones, alteraciones metabólicas, alteraciones de la función renal, alteraciones hidroelectrolíticas. Respecto de estas últimas, particularmente en relación a diarreas, se produce baja concentración de potasio intracelular, lo que está asociado a un mayor riesgo de muerte. Señale lo correcto:",
    "options": [
      "Sus manifestaciones clínicas son: distensión abdominal, vómitos, disminución o ausencia de ruidos hidroaéreos, hiporreflexia y trastornos del ritmo cardíaco.",
      "La baja concentración de potasio intracelular promueve la excreción renal de sodio y agua lo que justifica la aparición de edema.",
      "En deshidratación grave, se produce alcalosis metabólica, con inhibición de la secreción renal e intercambio por Hidrógeno y la célula expulsa K al medio extracelular.",
      "Para el tratamiento de la Hipopotasemia, deben usarse sueros que contengan glucosa para que la liberación de insulina promueva la entrada de potasio a la célula."
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 209 · pág. 76",
    "fixedOrder": false
  },
