    "stem": "Mujer de 40 años sin antecedentes médicos de importancia acude al servicio de urgencias. Refiere que presenta un dolor de tipo cólico localizado en el epigastrio desde hace 6 horas, luego de la ingesta de comida con contenido graso, se acompaña de nausea que llega al vómito de contenido alimentario que no ha modificado el dolor. Al examen físico la paciente presenta tinte ictérico en escleras, refiere dolor a la palpación profunda en el hipocondrio derecho. ¿Qué examen es el más apropiado realizar?",
