  {
    "id": "html-211",
    "subject": "Banco general de medicina",
    "stem": "Una de las infecciones parasitarias prevalentes en la infancia es por oxiuros o Enterobius vermicularis, que es un nematodo pequeño (1 cm de largo), blanco, filiforme o gusano redondo, que habitualmente habita el ciego, el apéndice y las áreas adyacentes del íleon y colon ascendente, a través de contaminación fecal oral. Respecto de la infección por Enterobius vermicularis, señale lo correcto:",
    "options": [
      "La migración aberrante a sitios ectópicos ocasionalmente puede conducir a apendicitis, salpingitis crónica, enfermedad inflamatoria pélvica, peritonitis, hepatitis y lesiones ulcerativas en el intestino grueso o delgado.",
      "Para el diagnóstico microscópico, el examen de coprológico muestra huevos del parásito y 1 examen detecta el 99 % de las infecciones.",
      "Se deben tratar a individuos infectados y su familia con imidazólicos, como Metronidazol es el tratamiento de elección y da como resultado tasas de curación superiores a 90%.",
      "La prevalencia de la infección por oxiuros es mayor en niños menores de 5 años."
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 211 · pág. 77",
    "fixedOrder": false
  },
