    "id": "html-212",
    "subject": "Banco general de medicina",
    "stem": "Respecto de la Infección de Vías Urinarias ( IVU ) en niños, señale lo correcto:",
    "options": [
      "La pielonefritis se caracteriza por alguno de los siguientes síntomas o por todos ellos: dolor abdominal, de espalda, dolor en el costado, fiebre, malestar, náusea, vómitos y, ocasionalmente, diarrea.",
      "Los recién nacidos pueden mostrar síntomas específicos, tales como disuria, polaquiuria, urgencia y tenesmo miccional, orina turbia y de mal olor con dolor en fosas lumbares.",
      "La pielonefritis es la infección bacteriana grave menos común en bebés menores de 24 meses de edad.",
      "Es frecuente la infección renal que se produce por diseminación hematógena, como en la endocarditis o en algunos neonatos bacteriémicos."
    ],
