    "source": "Banco educativo EstudiaMed · pregunta 212 · pág. 78",
    "fixedOrder": false
  },
  {
    "id": "html-213",
    "subject": "Banco general de medicina",
    "stem": "El tratamiento de la pielonefritis en pacientes pediátricos, debe ser adecuado y oportuno, para evitar complicaciones. Respecto del tratamiento. Señale lo correcto:",
    "options": [
      "Un curso de antibióticos de 7-14 días que es capaz de alcanzar niveles significativos en tejidos es adecuada en pielonefritis; Las vías oral y parental son igualmente eficaces.",
      "Los niños deshidratados, con vómito, no pueden beber, tienen infección complicada, o con urosepsis, deben ser tratados en forma ambulatoria.",
      "Ante síntomas leves o de diagnóstico dudoso, el tratamiento debe iniciarse con un curso de quinolonas.",
      "La nitrofurantoína debe usarse habitualmente en niños con IVU febril, porque alcanza niveles significativos de tejido renal."
