  {
    "id": "html-214",
    "subject": "Banco general de medicina",
    "stem": "Un varón de 55 años, es traído a urgencias por el personal prehospitalario con inmovilización cervical y en tabla rígida. Le comentan que siendo el conductor de una motocicleta, sufre un accidente de tránsito en el que se produce un impacto frontal (con uso de casco) contra una pared. Desde su evaluación prehospitalaria presenta una Escala de Coma de Glasgow: 12 (RO: 3; RV: 4; RM: 5). SV: TA: 130/90 mmHh; FC: 105 lpm; FR: 19 rpm; T: 36 °C, Sat. 92%. Ausencia de lesiones en cuero cabelludo, sin equimosis periorbitaria, presenta pupilas isocóricas y fotorreactivas, a la palpación de la columna torácica realiza un quejido, se evidencia alteración sensorial al dolor y temperatura por debajo de la caja torácica, en el examen motor muestra ausencia de movimiento en las extremidades inferiores. La tomografía de columna torácica muestra fractura de cuerpos vertebrales a nivel de T5 a T8 con desplazamiento posterior de fragmentos óseos. ¿Cuál sería la lesión más probable en este paciente?",
