    "stem": "Mujer de 31 años, con antecedente de 4 abortos de repetición, acude por astenia desde hace 6 meses, sin otra sintomatología. A la exploración física: Paciente en buen estado general, TA: 115/75 mmHg, FC: 74 lpm, FR: 12 rpm, SatO2 96%, soplo sistólico pulmonar grado 3/6, resto sin alteraciones. La analítica sanguínea en ayunas muestra: Hb 13.7 g/dL, Hto 41.1%, VCM: 87 fL, leucocitos 8 750/mL, Neutrófilos 63%, linfocitos 33%, eosinófilos 1%, monocitos 1%, basófilos 2%, plaquetas: 200 000/µL; Glucosa 87 mg/dL, creatinina 0.7 mg/dL, ácido úrico: 5.20 mg/dL. Colesterol total: 188 mg/dL, HDL: 50 mg/dL, LDL: 97 mg/dL, triglicéridos: 135 mg/dL. Perfil hepático, tiroideo, coagulación y EMO normales. INR: 1.1. Anticoagulante lúpico y anticuerpos anticardiolipina positivos a título alto. Eco transtorácico y transesofágico: masa móvil de 3.2 x 1.2 cm en el tracto de salida del ventrículo derecho (VD) en forma de racimo que prolapsa en sístole hacia la arteria pulmonar. ¿Cuál es el tratamiento de primera elección para esta paciente?",
