  {
    "id": "html-216",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 20 años con normopeso es llevada a la emergencia del hospital por presentar letargia. De acuerdo a sus familiares, la paciente presentó un malestar estomacal hace cuatro días con náusea, vómito, y dolor abdominal. Desde entonces, el vómito ha desaparecido, pero persisten los otros síntomas que se han intensificado, además de una disminución del apetito. Adicionalmente, en las últimas semanas ha experimentado una pérdida de 4 kg de peso corporal, asociado a una sed excesiva. Refiere fecha de la última menstruación hace 10 días. La paciente toma ocasionalmente cervezas, niega consumo de tabaco o drogas ilícitas. No relata antecedentes familiares. Al examen físico presenta una temperatura de 37.2 °C, presión arterial de 100/56 mmHg, pulso de 120/min (regular pero débil), y respiraciones de 28/min (rápidas y profundas). La saturación de oxígeno es de 97%, se encuentra letárgica, pero responde a estímulos y mueve sus extremidades espontáneamente. La química sanguínea muestra glucemia de 300 mg/dL, cetonas 3.0 mmol/L. El análisis de orina mostró un valor de 20 mg/dL de cetonas. ¿Cuál es el diagnóstico más probable que presenta esta paciente?",
