  {
    "id": "html-218",
    "subject": "Banco general de medicina",
    "stem": "Un paciente de 77 años es traído a la emergencia por sus familiares por presentar dolor abdominal. El dolor comenzó 18 horas antes y se localiza en el cuadrante inferior izquierdo del abdomen. El dolor empezó insidiosamente y ha aumentado mucho en intensidad hasta alcanzar 7/10 en opinión del paciente. Ha tenido dos episodios de vómito alimentario al inicio del dolor. No ha tenido evacuación intestinal ni ha eliminado flatos en 18 horas. El dolor no tiene irradiación y es continuo. Sus antecedentes personales son importantes por un sangrado digestivo bajo hace 4 años. Al examen físico su temperatura es de 37.9 grados; FR: 17/min; FC: 96/min; TA: 150/85 mm Hg. El examen cardiopulmonar es normal. El abdomen se aprecia ligeramente distendido. Es suave pero hay resistencia muscular a la palpación del lado izquierdo en donde se produce dolor intenso a la palpación profunda. No hay dolor de rebote. Los ruidos hidroaéreos están diminuidos. La biometría hemática muestra leucocitosis de 12.000/ mm3 y neutrofilia. La creatinina está en 1.1 mg/dL. ¿Cuál es el diagnóstico más probable?",
