    "id": "html-219",
    "subject": "Banco general de medicina",
    "stem": "Un paciente de 56 años acude a la consulta de gastroenterología tras haber tenido tres episodios de diverticulitis aguda, el último hace un mes. En todas las ocasiones fue tratado con reposo digestivo por unos días y dieta sin fibra por unas semanas hasta continuar luego con la dieta habitual. Siempre siguió las recomendaciones que se le hicieron pero sus problemas persisten. El paciente se encuentra asintomático y ha empezado desde hace una semana, por recomendación de su médico personal, una dieta con fibra. El paciente se encuentra en buen estado general. Sus signos vitales son normales, su examen físico es normal y su analítica sanguínea es totalmente normal. ¿Cuál es la recomendación que corresponde respecto al tratamiento?",
    "options": [
