    "subject": "Banco general de medicina",
    "stem": "Mujer de 40 años, acude a consulta por secreción vaginal dos días pos coito, sin otros síntomas acompañantes. Tiene una pareja estable desde hace 3 años. Al examen físico presenta: signos vitales normales, leucorrea grisácea fétida en escasa cantidad, vagina y cérvix sin anomalías. Resto de la exploración normal. La preparación en fresco de la secreción vaginal muestra células guía al microscopio, el pH vaginal es de 5 y la prueba de aminas es positiva. ¿Cuál es el principal agente causal del cuadro descrito?",
