    "id": "html-221",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 35 años se encuentra en seguimiento de puerperio luego de haberse sometido a una cesárea programada a la semana 37 de gestación debido a hipertensión arterial diagnosticada en la semana 24, que respondió parcialmente a tratamiento con nifedipina. El procedimiento se realizó sin complicaciones y a las 24 horas la paciente no refiere síntomas de relevancia. Su historia clínica refiere como único antecedente una gesta previa con diagnóstico de preeclampsia sin secuelas. Actualmente el examen físico evidencia tensión arterial de 180/90 mmHg, frecuencia cardíaca 90 latidos por minuto, frecuencia respiratoria 16 por minuto. Abdomen: suave, depresible, no doloroso. Fondo uterino: O – 1. Laboratorio: Plaquetas 200.000 mm3 creatinina 0.9 mg/dL, ALT 25 U/L. Proteinuria: positiva. A las 48 horas postparto la paciente presenta crisis convulsivas tónico clónico generalizadas. ¿Cuál es el diagnóstico inicial más probable?",
