    "id": "html-222",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 45 años acude a emergencia por presentar desde hace 48 horas, dolor en el miembro inferior derecho en relación a un aparente traumatismo con el borde de su ropero. Antecedentes: hipertensión arterial hace 4 años. Al examen físico presenta: FC: 98 lpm, TA: 125/86 mmHg, temperatura: 38 °C, FR: 16 rpm y Sat O2: 96%. En el tercio medio de la pierna derecha se objetiva una placa eritematoedematosa, caliente, brillante, dolorosa a la digitopresión de aproximadamente 10 cm de diámetro, con aspecto de piel de naranja y límites de la lesión bien demarcados. Pulsos distales presentes. Resto de la exploración normal. ¿Cuál es el diagnóstico más probable?",
