    "stem": "Mujer de 48 años, acude por consulta externa, refiere que hace un año presenta caída del cabello, piel seca, disminución de libido sexual, alteración en los ciclos menstruales, aumento de peso. A los exámenes: HB: 12.5 gr/dl plaquetas 140 000 mcL, FSH: 19 mlU/mL (4.5 a 21.5 mIU/L), LH 24 UI/L (5 a 25 UI/L) TSH 5.2 mUI/L (0.5 a 4.5 mUI/L), T4 libre normal, ATPO 75 ng/ml (60 ng/mL). Al examen físico PA 100/60 mm Hg, FC de 85 lpm, IMC de 29.5 Kg/m2, piel seca en manos, uñas quebradizas, resto de examen físico en parámetros normales. ¿Cuál es el diagnóstico más probable?",
