    "id": "html-224",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 45 años acude a urgencias por presentar desde hace 36 horas dolor abdominal de gran intensidad, constante, localizado en epigastrio y región periumbilical e irradiado a flancos y a hemiabdomen inferior, acompañado de náusea, vómito y distensión abdominal. Antecedente: litiasis vesicular. A la exploración física presenta: TA: 80/60 mmHg, FC: 115 lpm, FR: 24 rpm, T: 38 °C, SpO2 94%. Abdomen: RHA disminuidos, dolor generalizado a la palpación y rigidez muscular abdominal en grado variable, se evidencia signo de Cullen y de Turner. Resto de la exploración normal. Los exámenes complementarios muestran: Hb: 18.9 g/dL, Hto: 44.3%, leucocitos 14 000/µL, neutrófilos: 75%, linfocitos: 20%, plaquetas: 252 000, sodio: 124 mEq/L, potasio: 3.37 mEq/L, cloro: 100 mEq/L, calcio: 1.50 (2.13 a 2.55 milimol/L), magnesio: 1.9 (de 0.85 a 1.10 mmol/L), creatinina: 0.78, BUN: 7.4 (7 y 20 mg/dL). Glucemia 130 mg/dl, amilasa: 537 U/l y lipasa: 6 660 U/l. Pruebas de coagulación normales. ¿Cuál es la prioridad en el tratamiento inicial de este paciente?",
