    "stem": "Mujer de 34 años acude a consulta para programación de su esplenectomía, debido a que entre sus antecedentes personales se incluyen púrpura trombocitopénica idiopática en tratamiento con prednisona 50mg/ día. Al examen físico se palpa esplenomegalia, presencia de petequias en extremidades superiores e inferiores. El hemograma muestra plaquetas 25 000/mm3. ¿Contra cuál de las siguientes bacterias se recomienda la inmunización en esta paciente?",
