    "id": "html-226",
    "subject": "Banco general de medicina",
    "stem": "Paciente masculino de 68 años acude a emergencias traído por su hijo por tos seca desde hace 8 días. En las últimas 48 horas, presenta expectoración purulenta, dificultad respiratoria, fiebre de 39 °C, diaforesis nocturna, mialgias y dolor pleurítico en la región dorso lateral de hemitórax derecho. Se acompaña desde hace 24 horas de confusión mental y falta de ingesta oral. Antecedentes: hipertensión arterial controlada con Lisinopril. Al examen físico presenta: TA: 88/56 mm Hg, FC: 115 lpm, FR: 35 rpm, T: 38 °C, SpO2 88 %. Se objetiva tiraje intercostal inferior y matidez en hemitórax posterior derecho. Los exámenes muestran: urea 12 mmol/l, leucocitos 14 000/µL, neutrófilos 80 %, VSG 50 mm/h. Radiografía de tórax con infiltrado en base derecha. De acuerdo con el índice de gravedad de la clasificación CURB 65 ¿Cuál es el siguiente paso para el manejo de este paciente?",
