    "id": "html-227",
    "subject": "Banco general de medicina",
    "stem": "Un recién nacido de 1 día de vida es valorado en el servicio de neonatología porque presenta mucha salivación y su madre refiere que vomita todo lo que come. Antecedentes prenatales: su madre no se realizó chequeos, ni ecografías hasta el momento del parto. Antecedentes natales: producto de parto vaginal espontáneo a las 39 semanas de gestación, peso: 2400 g, Apgar 8 – 9 al nacimiento y a los 5 minutos respectivamente. Al examen físico FC: 140/min, FR 45/min, paciente irritable, con hambre, abundante sialorrea, se intenta colocación de sonda orogástrica sin éxito. Radiografía de tórax con medio de contraste evidencia saco esofágico proximal, sin comunicación con el estómago. ¿Qué cuadro probable presentó la madre del paciente durante el embarazo?",
