    "stem": "Mujer de 21 años acude a urgencias con labor de parto. Niega antecedentes médicos de importancia. Gestas 2 Parto 1 Aborto 0. Embarazo actual de 39 semanas por fecha de última menstruación. Al examen físico presenta tensión arterial 120/80 mmHg, frecuencia cardíaca 74 latidos por minuto, frecuencia respiratoria 16 por minuto. Abdomen: suave, depresible, no doloroso. Fondo uterino acorde a edad gestacional. Feto único, cefálico. Frecuencia cardíaca fetal: 100 latidos por minuto mantenida. Tacto vaginal: dilatado 6 cm, borrado 70 %. Actividad uterina 1 en 10 minutos repetida en 1 hora. La evaluación a los 30 minutos no evidencia cambios en frecuencia cardíaca fetal, actividad uterina y tacto vaginal. Monitoreo fetal: frecuencia cardíaca fetal: 100 latidos por minuto, desaceleraciones tardías, sin variabilidad. ¿Cuál es el manejo inicial más apropiado para esta paciente?",
