    "id": "html-229",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 40 años, que acude al servicio de emergencia por dolor abdominal, hace 24 horas localizado en mesogastrio, tipo cólico, de moderada intensidad (7/10), náusea, vómito por varias ocasiones en poca cantidad (50 ml), poliurea, sed. Antecedente: Diabetes mellitus 2 en tratamiento con insulina. Examen físico: presión arterial: 90/60 mmHg, frecuencia cardíaca: 107 por minuto. Paciente: somnolieta, Glasgow: 15/15. Boca: Mucosas orales secas, aliento afrutado, respiración de Kussmaul, Abdomen: suave, depresible, doloroso a la palpación profunda en mesogastrio, ruidos hidroaéreos presentes. Laboratorio: Glucosa: 300 mg/dl. Na: 135 mEq/l, K: 5mEq/L. Cl: 90 mEq/L. GSA: pH: 7, PCO2: 25 mmHg. Bicarbonato: 12 mEq/L. Anión gap: 28. Osmolaridad plasmática: 290 mOsm/L. EMO: nitritos: positivos piocitos: campo lleno, hematíes: campo lleno, bacterias:+++. ¿Cuál es el diagnóstico más probable?",
