    "stem": "Hombre de 35 años acude a emergencias tras caída desde su propia altura sobre el brazo derecho en extensión y separado del cuerpo, con posterior dolor de hombro derecho de 30 minutos de evolución. Es la segunda vez que presenta un cuadro clínico similar. No traumatismo craneal, ni pérdida de conocimiento tras la caída. Al examen físico, los signos vitales están dentro de la normalidad. Miembro superior derecho: en rotación externa y signo de charretera con pulsos distales y fuerza conservadas. Resto de la exploración normal. ¿Cuál es la principal lesión responsable de la recidiva en este paciente?",
