    "id": "html-231",
    "subject": "Banco general de medicina",
    "stem": "Le invitan a participar como investigador para una molécula que ha demostrado resultados favorables en animales para bajar la presión arterial. El estudio se encuentra en fase clínica y se ha decidido comenzar la administración del fármaco en personas residentes en un barrio urbano que tengan hipertensión arterial no controlada. Luego de culminar esta fase, se tiene previsto administrar el fármaco, en doble ciego, y compararlo con el tratamiento de primera línea estipulado en la guía local para esta patología. Usted decide no participar ya que el diseño vulnera principios éticos por haberse saltado una de las fases de la investigación. ¿Qué fase no se desarrolló en este caso?",
