    "stem": "Una mujer 31 años, acude a emergencias por cefalea de intensidad 10/10, de inicio súbito (2 horas de evolución), desencadenada por esfuerzo en la mañana. Se acompaña de náusea, niega otra sintomatología. Niega antecedentes clínicos relevantes. Al examen físico TA 130/80 mm Hg, pulso 83 por minuto, temperatura 36.8 °C, diaforética, álgida, consciente, orientada en las tres esferas, pupilas isocóricas normoreacticas, diplopía horizontal. Al examen fondo de ojo hay edema de papila. No se cuenta con estudios de imagen en el establecimiento. Tomando en cuenta la clínica de la paciente. ¿Cuál es el diagnóstico más probable?",
