    "stem": "Niño de 5 años es llevado al servicio de emergencias por presentar cuadro clínico de 6 días de evolución con fiebre muy alta que no cede a la administración de paracetamol. No refiere antecedentes personales de importancia y tiene las inmunizaciones para la edad. Al examen físico: FC: 135 /min, FR: 23/min, temperatura 39.6 °C. Presenta inyección conjuntival no exudativa bilateral, los labios están eritematosos, secos y agrietados, y la lengua es de color rojo brillante. Tiene una erupción polimorfa no vesicular en el tronco. Sus manos y pies están edematosos y sus palmas y plantas están eritematosas. ¿Cuál es el diagnóstico más probable del paciente?",
