    "stem": "Varón de 35 años atendido en consulta externa por vértigo. El episodio dura menos de un minuto y se genera por movimientos de la cabeza (rotar en la cama). Refiere cuadro similar hace un año, mismo que cedió espontánemamente sin dejar secuelas. Niega síntomas visuales o auditivos asociados. Niega antecedentes médicos de importancia. Al examen físico: tensión arterial 130/80 mmHg, frecuencia cardíaca 72 latidos por minuto, frecuencia respiratoria 16 por minuto. Nistagmo horizontal cuando el paciente está en decúbito lateral, de ambos lados. Usted sospecha la presencia de otoconías como agente etiológico del cuadro clínico. ¿Cuál es el tratamiento de primera elección para este paciente?",
