    "subject": "Banco general de medicina",
    "stem": "Mujer de 34 años, primigesta de 37 semanas con controles prenatales y ecografías normales. Acude a emergencia por cefalea persistente y edema en sus manos. Antecedentes: sin importancia. Al examen físico presenta: FC: 74/min, FR: 21/min, temperatura 36 °C, TA: 160/110 mmHg durante dos ocasiones con un intervalo de 15 minutos en el mismo brazo. Abdomen gestante con fondo uterino a término, feto único móvil, en presentación cefálica y con frecuencia cardiaca fetal (FCF): 155/min. Tacto vaginal: cérvix posterior cerrado. Los exámenes complementarios muestran: proteínas en orina ++ mediante tira reactiva. Plaquetas 210 000/uL, TGO 32 UI/L, TGP 30 UI /L, creatinina sérica 0.7 mg/dL. ¿Cuál es el tratamiento de elección para prevenir convulsiones en esta paciente?",
