    "stem": "Paciente de 75 años que consulta por tumoración en la región supraclavicular izquierda de 1 mes de evolución con pérdida de peso, palidez, anorexia cansancio, relata haber tenido coronariopatía diagnosticada por el médico hace 3 años, y entre la medicación recibida consta aspirina, clopidrogel, omeprazol y valsartan, entre los que recuerda. Examen de laboratorio revela: Hemoglobina 9 g/dl; Hematocrito 29 %; PCR 1.5 mg/l; Creatinina 1.09 mg/dl. ¿Cuál de los siguientes síntomas y signos relatados y encontrados en el examen físico, es la mejor opción que se relacione con metástasis por cáncer gástrico?",
