    "stem": "Varón de 25 años acude a consulta externa para revisión de exámenes por estudio de enfermedad de transmisión sexual. No refiere antecedentes médicos de importancia. Indica tener vida sexual activa con 2 parejas heterosexuales y no refiere la práctica de sexo anal. Al examen físico los signos vitales se encuentran normales. En área genital se evidencia úlcera no dolorosa con adenopatías alrededor de la zona. Laboratorio: Creatinina 1 mg/dL; VDRL positivo, Prueba de reagina plasmática rápida positiva (títulos 1:32). Examen de orina: nitritos y esterasa leucocitaria negativos. Cultivo de orina negativo. HIV: negativo. ¿Cuál es el fármaco de elección para este paciente?",
