    "stem": "Varón de 60 años, atendido en consulta externa por edema de miembros inferiores. Refiere que 3 semanas antes de su molestia inició tratamiento farmacológico para hipertensión arterial. No presenta reacciones alérgicas medicamentosas conocidas. Al examen físico presenta: tensión arterial de 140/90 mmHg, temperatura 37 °C, frecuencia cardíaca de 80 latidos por minuto, frecuencia respiratoria 16 latidos por minuto, Sat O2 aire ambiente 94 %. Exploración cardiopulmonar normal. Miembros inferiores: pulsos distales presentes, edema maleolar bilateral +/+++, sin fóvea. ¿Cuál es el fármaco causante del efecto adverso en este paciente?",
