    "stem": "Mujer de 60 años acude a urgencias por lesión cutánea en el tórax. Indica que hace 48 horas inició con dolor en el área afectada y posteriormente aparecen lesiones eritematosas pruriginosas en la piel. Niega antecedente de inmunodepresión. Al examen físico: tensión arterial 120/80 mmHg, frecuencia cardíaca 100 latidos por minuto, frecuencia respiratoria 14 por minuto. Temperatura 37,2 °C. Tórax anterior derecho: múltiples lesiones vesiculares sobre un fondo eritematoso y con costra circunscritas al dermatoma T5. Cardiopulmonar: normal. Neurológico: sin focalidad. Resto de la exploración normal. ¿Cuál es el diagnóstico más probable?",
