    "stem": "Madre soltera analfabeta de 25 años. Está dudosa de participar en una investigación del Subcentro de Salud de su comunidad que iniciará mañana. Los investigadores le han indicado de manera oral que se trata de obtener el “Coeficiente de correlación de la translocación axial de los eslabones 1821 de la cadena isométrica del gen 88” y que los resultados servirán para resolver definitivamente los problemas COVID de su comunidad. Le han garantizado que por su participación recibirá doble dosis de complemento alimentario para su hija, así como un cuidado más esmerado de su salud y que al terminar el estudio se le acreditará un bono de $150. ¿Cuáles son los principios bioéticos de la investigación que se hallan evidentemente comprometidos?",
