    "id": "html-251",
    "subject": "Banco general de medicina",
    "stem": "Se presenta el caso de un paciente de 58 años, residente de Quito, que acude por una lesión en la punta de la nariz. La lesión apareció hace dos meses aproximadamente, inicialmente como una descamación pruriginosa con un área deprimida central que ahora se observa como una costra que sangra ocasionalmente. Si bien la lesión no ha crecido mayormente, tampoco ha mejorado, por lo que acude. No refiere antecedentes patológicos de relevancia o síntomas acompañantes. Al examen físico se observa una lesión papular de 2cm con borde descamativo y color perlado. En el centro de la lesión se observa una úlcera central de 3mm, ligeramente deprimida y con centro hemorrágico. ¿Cuál sería el procedimiento diagnóstico más recomendado en este caso?",
