    "id": "html-254",
    "subject": "Banco general de medicina",
    "stem": "Niño de 10 años es traído a la emergencia por su madre por presentar dolor abdominal. El dolor empezó hace 24 horas, sin causa aparente, y se localizó inicialmente en el epigastrio siendo constante y aumentando progresivamente de intensidad hasta alcanzar 8/10. El dolor se acompaña de vómito de contenido alimentario por 3 ocasiones; diarrea por 2 ocasiones, acuosas, también por pérdida del apetito y fiebre. Al cabo de 6 horas el dolor se irradió al cuadrante inferior derecho del abdomen que es el sitio del dolor al momento. El niño no tiene antecedentes patológicos personales ni familiares de importancia. Al examen físico la temperatura es 37.8 °C; FC: 92 /min; FR: 16/min; TA: 110/60 mmHg. El paciente muestra facies de dolor, se encuentra en posición fetal. El abdomen es plano levemente doloroso a la palpación superficial e intensamente doloroso a la palpación y profunda en la fosa ilíaca derecha. Hay dolor de rebote limitado a la fosa ilíaca y el signo de Rovsing es positivo. Los exámenes revelaron: leucocitos 16 000 /mm3, neutrófilos 50 %, linfocitos 50 %, plaquetas 350 000 /mm3, Proteína C reactiva (PCR) 9 mg/l. ¿Cuál es el diagnóstico más probable?",
