    "subject": "Banco general de medicina",
    "stem": "Una paciente gestante de 34 años acude a consulta por presentar manchas obscuras en la cara. La paciente, residente de Ibarra, refiere que notó las lesiones hace aproximadamente dos meses en ambas regiones malares y posteriormente puente de la nariz. Se ha tratado con cremas hidratantes sin resultados. No refiere hemorragia, secreción o descamación en las lesiones y no se acompañan de prurito o dolor. Indica que, debido a su complexión morena, no suele usar protector solar. Como único antecedente de relevancia se menciona su embarazo de 28 semanas, mismo que ha cursado sin complicaciones. Al examen físico se observan lesiones maculares convergentes hiperpigmentadas, de bordes irregulares bien definidos que cubren ambas prominencias malares además de lesiones más pequeñas en el puente nasal y frente. El examen físico evidencia, como único hallazgo relevante adicional, una hiperpigmentación lineal entre el borde inferior del ombligo y la región del pubis. Con la información disponible. ¿Cuál es la sospecha diagnóstica más probable?",
