    "stem": "Mujer de 34 años acude a consulta externa porque desde hace aproximadamente 6 meses, presenta una masa visible y palpable en la región anterior del cuello, indolora y que no ha crecido. Se acompaña de estreñimiento, astenia, síntomas depresivos y aumento de peso de 58 a 61 Kg sin haber modificado sus hábitos alimentarios. Está casada desde hace 12 años y no se ha embarazado pese a una vida sexual activa. Antecedentes personales sin importancia. Antecedentes familiares: madre con hipotiroidismo, prima paterna con hipertiroidismo. Al examen físico: talla 157 cm, peso 61 Kg, TA: 110/80 mmHg, FC: 55 lpm, FR: 14 rpm, T: 36 °C, SpO2 96 %. Piel seca, pálida y fría. Tiroides: visible y palpable, no dolorosa, móvil con la deglución y de consistencia firme. Maniobra de Pemberton negativa. En la exploración mamaria se objetiva galactorrea bilateral. Resto del examen normal. ¿Cuál es el diagnóstico más probable?",
