    "id": "html-275",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 25 años, oficinista, acude a la consulta preocupada por el riesgo de malformaciones congénitas del antiepiléptico que toma. Tiene una historia de epilepsia desde los 17 años. Ha contraído matrimonio hace un mes y planea procrear familia en un futuro inmediato. Dos primas también tienen epilepsia. La paciente toma regularmente la medicación, pero continúa presentando convulsiones con una frecuencia de un episodio cada mes. La exploración neurológica es normal. Un EEG es anormal, con descargas rítmicas generalizadas de poliespiga-onda lenta de 4.5 Hz, una IRM de encéfalo es normal. Al conocer usted el antiepiléptico que toma la paciente, le indica que es preferible cambiarlo a otro fármaco con menor riesgo de efectos teratogénicos. ¿Cuál de los siguientes anticonvulsivantes tiene riesgo alto de efectos teratogénicos?",
