    "subject": "Banco general de medicina",
    "stem": "Paciente femenina de 46 años consulta por tos productiva, malestar general y dolor torácico de 2 meses de evolución, que se exacerba en último mes junto con alza térmica no cuantificada que controla con 1 g de paracetamol cada 8 horas. Ha sido valorada por varios facultativos quiénes le han indicado medidas generales como mantener el paracetamol y recibe amoxicilina con ácido clavulánico por 7 días y azitromicina por 3 días, sin mejoría de los síntomas. Refiere pérdida de peso de 3 Kg en últimos 2 meses sin causa aparente y astenia. Al examen físico, TA: 120/70 mmHg, frecuencia cardíaca: 85 x min, frecuencia respiratoria: 15 x minuto, T: 38.5 ºC, sat O2. 90 %, IMC: 21. Conjuntivas rosadas, mucosas orales semihúmedas. Corazón: ruidos cardíacos rítmicos, no soplos. Pulmonar: MV abolido en pulmón derecho, matidez a la percusión en base derecha. Se realiza una radiografía de tórax con evidencia de derrame pleural. Se realiza punción de líquido pleural, encontrándose: pH 7.38, cociente entre proteínas de líquido pleural/sérico > 0.6, adenosina desaminasa (ADA): 46 U/L, linfocitos 75 %. ¿Cuál sería su sospecha etiológica en este caso?",
