    "stem": "Paciente de 6 semanas de vida, que acude a consulta externa por presentar ictericia desde el nacimiento. Madre menciona deposiciones claras (acolia). Se le han realizado múltiples exámenes, refirieron que se trataba de ictericia por lactancia materna, sin embargo se le suspendió lactancia materna por 3 días y se le han otorgado baños diarios de sol sin mejoría. Al examen físico paciente en regular estado general, signos vitales normales, hepatomegalia 4 centímetros bajo reborde costal, ictericia generalizada, no otras anomalías. Exámenes: biometría normal, bilirrubina total 10 mg/dl, bilirrubina directa 8 mg/dl, test de Coombs negativo, Citomegalovirus IgM negativo, IgG positivo, Toxoplasma IgM e IgG negativos, alanina-aminotransferasa 160 UI/l (normal 4 a 36 UI/l), aspartato aminotransferasa 130 UI/l (normal hasta 40 UI/l), gamaglutamil transferasa 390 UI/l (normal 5 a 40 UI/l), reticulocitos 2%, proteína C reactiva 2 mg/l (normal hasta 4mg/l). ¿Cuál es el diagnóstico más probable en este paciente?",
