    "stem": "Un niño de 6 años, pesa 20 kg. Desde hace 7 días presenta dolor abdominal en mesogastrio, tipo cólico con aparición post prandial. Luego del dolor presenta diarreas líquidas, abundantes, explosivas, blanquecinas, espumosas, esteatorréicas, mal olientes, con restos alimentarios. Hay flatulencia intensa. Luego de las deposiciones calma el dolor. Su estado general es bueno. Se repiten de 3 a 4 veces al día. El abdomen algo abombado y timpánico, presenta dolor a la palpación profunda, especialmente en el lado derecho del mesogastrio. Seleccione la posible patología y el tratamiento correcto:",
