    "stem": "Una paciente de 32 años se presenta en la emergencia del hospital local con sangrado genital. La paciente cursa la décima semana de su cuarto embarazo habiendo terminado los otros tres en abortos espontáneos. Sus antecedentes patológicos personales son importantes por un cuadro de embolia pulmonar a los 28 años y dos episodios de trombosis venosa profunda a los 22 y 26 años. Su FC: 80/min; FR: 14 /min; T: 37 grados C; TA: 100/70 mmHg. Su índice de masa corporal es de 22. El examen físico es normal excepto por la visualización del cuello uterino abierto y con sangrado activo. ¿Cuál de los siguientes resultados es el que encontrará con mayor probabilidad?",
