    "stem": "Un varón de 28 años acude a la emergencia por presentar dolor en la región lumbar derecha. El dolor es de inicio súbito y comenzó hace aproximadamente 4 horas. El dolor ha ido incrementando en intensidad y actualmente refiere que éste es de tipo cólico, irradiándose hacia la región inguinal derecha. No hay disuria, sin embargo, hay presencia de hematuria. Sus antecedentes personales incluyen enfermedad de Crohn desde hace 9 años. No consume alcohol ni tabaco. Al examen físico la TA es de 140/90 mm Hg; FC: 98/min; FR: 23/min; T: 36.7 °C. El paciente está intranquilo, con dolor intenso, observándose dolor en la puño percusión en la región lumbar derecha. El resto del examen físico es normal. El hemograma, electrolitos, glucosa, ácido úrico, albúmina, urea y creatinina son normales. La URO-TAC sin contraste muestra una lesión hiperdensa ubicada en medio del uréter derecho. ¿Cuál de las siguientes opciones explica con mayor probabilidad la causa de obstrucción en este paciente?",
