    "stem": "Juan de 13 años, sufre traumatismo nasal agudo mientras juega fútbol, es valorado en el centro de salud por epistaxis de fosa nasal izquierda y deformidad del dorso nasal, al ceder la epistaxis, le prescriben ibuprofeno 600 mg cada 8 horas durante 3 días y hielo local. A los 3 días presenta equimosis y edema nasal y palpebral izquierdo, dolor en la zona con obstrucción nasal que no le deja respirar bien. No fiebre. A la exploración se aprecia edema y abombamiento de la mucosa del tabique nasal, la Rx muestra fractura de huesos propios nasales no desplazada. ¿Cuál es la complicación más frecuente que presenta Juan al no ser diagnosticado y tratado precozmente?",
