    "stem": "Se presenta el caso de un paciente de 57 años que busca dejar de consumir alcohol. Refiere que inició su consumo en la adolescencia y ha aumentado progresivamente, al punto de consumir la sustancia todos los días en los últimos 5 años. Su consumo le ha generado problemas en el trabajo, con su familia y recientemente le han diagnosticado de hígado graso, por lo que pide ayuda. El paciente se encuentra nervioso ya que no ha bebido en cuatro días y presenta temblores, nauseas constantes y vómito ocasional de contenido gástrico. No refiere otros síntomas acompañantes. ¿Qué medida terapéutica sería la más recomendable en este caso?",
