    "stem": "Hombre de 38 años, acude a la emergencia por epigastralgia intensa (EVA 10/10) de 6 horas de evolución, de inicio repentino. No náuseas, no vómitos, ni fiebre. Antecedentes: lumbalgia crónica que precisa ingesta de diclofenaco sódico 50 mg tres veces al día durante 2 semanas. Hace 1 mes le realizaron una endoscopia digestiva alta, donde se evidenció una úlcera duodenal y le prescribieron tratamiento que no tomó. Al examen físico presenta: Facies álgica. Consciente y orientado en las tres esferas. TA: 115/72 mmHg; FC: 96 lpm; FR: 20 rpm. T: 36 °C. Cardiopulmonar: normal. Abdomen: RHA disminuidos, tenso, poco depresible, doloroso a la palpación superficial y profunda en epigastrio, reacción peritoneal a la descompresión en todos los cuadrantes. Tacto rectal: no doloroso a la digitopresión, esfínter normotónico, ampolla con heces marrón claro, no se objetivan tumoraciones ni signos de sangrado activo. Resto de la exploración normal. ¿Cuál es el diagnóstico más probable que presenta el paciente?",
