    "stem": "Hombre de 45 años llega a emergencia del hospital con heridas superficiales por arma blanca en antebrazos y abdomen. Antecedentes de ansiedad y autoagresiones. Los familiares que lo trasladan, refieren intento de suicidio en el domicilio del paciente. Durante la evaluación de la urgencia, se procede a suturar las heridas; sin embargo, manifiesta eventos de ansiedad generalizada con preocupación excesiva, incontrolable, persistente y carente de realismo acerca de situaciones futuras, al punto que, la intervención de micro cirugía resulta accidentada e interrumpida debido al comportamiento poco colaborador del paciente. ¿Qué tratamiento es el más recomendable para este momento?",
