    "stem": "Una mujer de 35 años es ingresada para realizar tiroidectomía total con vaciamiento ganglionar central. No refiere ninguna sintomatología al ingreso. Sus antecedentes personales incluyen hipotiroidismo hace 5 años, toma levotiroxina 50 microgramos /día. Cáncer papilar de tiroides diagnosticado hace 2 meses, que es la causa de la cirugía que se va a realizar la paciente. Se realiza la cirugía sin complicaciones; sin embargo, a las 4 horas post-quirúrgicas paciente refiere parestesias y espasmos musculares en cara, manos y pies. Al examen físico FC: 87/min, FR: 20/min, TA: 100 /65 mmHg, temperatura: 36.7 °C. Espasmo facial, especialmente de la comisura labial al percutir el nervio facial por delante de la oreja y espasmo muy doloroso del carpo al aumentar la presión del manguito de tensión arterial sobre el brazo por encima de las cifras sistólicas. El hemograma muestra 10.000 / mm3 con 60 % de segmentados neutrófilos. La química sanguínea muestra glucosa 89 mg/dl, creatinina 1 mg/dL, sodio 138 mEq/L, potasio 4 mEq/L, magnesio sérico de 2 mEq/L, calcio sérico total de 7.1 mg/dL. ¿Cuál de las siguientes acciones es la que corresponde hacer en forma inmediata?",
