    "stem": "Un hombre de 78 años acude a emergencia por presentar dolor y distensión abdominal de 5 días de evolución. El dolor inicialmente fue difuso y leve, hace 24 horas se intensifica y se acompaña de importante distensión abdominal y ausencia de flatos. No ha presentado vómitos. Sus antecedentes personales incluyen estreñimiento desde hace 5 años en tratamiento con dieta rica en fibra y líquidos. El examen físico FC: 90/min, FR: 24/min, TA: 130/90mmHg, temperatura: 37.7 °C. El abdomen se encuentra con importante dilatación, doloroso de forma difusa, sin irritación peritoneal y ausencia de ruidos hidroaéreos. La radiografía abdominal muestra asa de segmento de colon izquierdo muy dilatada que se extiende hacia el cuadrante superior derecho (imagen en grano de café), ausencia de gas en el recto. El hemograma muestra 15.500 / mm3 con 90 % de segmentados neutrófilos. La química sanguínea muestra glucosa 89 mg/dl, creatinina 2 mg/dl, sodio 136 mEq/L y potasio 3.7 mEq/l. ¿Con qué diagnóstico es compatible el cuadro descrito?",
