    "id": "html-351",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 12 años acude a consulta externa por cuadro de alteración de la de conciencia. Su madre indica que la paciente presentó un cuadro de pérdida del estado de alerta que generó caída de propia altura, inició con un grito y se acompañó de “ataques” con movimientos desordenados, al despertar la paciente tiene amnesia del evento. Niega antecedentes médicos de importancia. Asintomática. Al examen físico: Signos vitales normales. Boca: signos de mordedura de lengua. Escoriación a nivel de codo derecho. No focalidad neurológica. ¿Cuál es el diagnóstico de este cuadro clínico?",
