    "id": "html-352",
    "subject": "Banco general de medicina",
    "stem": "Paciente de 10 años con ausencia de descenso de testículo izquierdo, refiere intenso dolor escrotal de inicio súbito y sudoración sin traumatismo previo. No fiebre ni otros síntomas acompañantes. El eco Doppler muestra disminución del flujo sanguíneo intratesticular izquierdo. ¿Qué espera encontrar en la exploración física de este paciente? 1. La elevación del testículo izquierdo hacia el canal inguinal disminuye el dolor. 2. El testículo izquierdo está ascendido y horizontalizado. 3. El reflejo cremastérico está conservado. 4. El signo de Gouverneur es positivo. 5. El testículo izquierdo está descendido y verticalizado. 6. El signo de Prehn es negativo.",
