    "stem": "Hombre de 26 años acude a consulta de medicina interna preocupado porque durante el último mes ha presentado mucha sed, ingiriendo hasta 6 litros de líquidos al día. Adicionalmente, aumento de la frecuencia urinaria levantándose a orinar hasta 5 veces en la noche. Al examen físico: TA: 115/75 mmHg, FC: 70/min, FR: 20/min, temperatura 36.2°C. No presenta signos de deshidratación. Resto del examen físico sin alteraciones. Se calcula osmolaridad urinaria en 24 horas de 300 mOsm / L. Se realiza una prueba de privación de líquidos, pero no produce un aumento de la osmolaridad de la orina. Se decide administrar desmopresina lo que provoca incremento de la osmolaridad urinaria. En ninguno de los análisis de orina se detecta glucosuria. ¿Cuál es el diagnóstico más probable de este paciente?",
