    "stem": "Un hombre de 34 años, soltero, es evaluado en la consulta de un centro de salud. Durante el interrogatorio el paciente refiere haber presentado diarrea hace 15 días. Hoy presenta dolor y enrojecimiento ocular, acompañado de dolor en las articulaciones de sus muñecas y ambos pies, disuria y úlceras en su boca. El examen ocular revela enrojecimiento y una secreción conjuntival mucoide. El examen bucal evidencia lesiones aftosas en la zona sublingual. Se observa placas eritemato escamosas en las palmas de sus manos. No hay evidencia de inflamación articular, aunque sí hay dolor a la presión. No se explora la región inguinogenital. ¿Cuál de los siguientes diagnósticos serían más probable en este paciente?",
