    "stem": "Un paciente masculino, de 28 años, fumador. Desde hace 3 semanas presenta tos seca, rinorrea cristalina, odinofagia. No registra fiebre. No tiene disnea ni sibilancias. Se establece el diagnóstico de bronquitis aguda y se decide iniciar manejo inicial primario. Seleccione el enunciado correcto:",
