    "stem": "Paciente de 6 meses de edad, sin antecedentes patológicos personales ni familiares relevantes. Desde hace 4 días presenta tos acompañada de rinorrea, coriza y alza térmica no cuantificada. Hace 12 horas se suma respiración áspera y ruidosa. Presenta retracciones costales inferiores y sibilancias difusas en ambos campos pulmonares. ¿Cuál es el diagnóstico clínico?",
