  {
    "id": "html-369",
    "subject": "Banco general de medicina",
    "stem": "Paciente masculino de 38 años, chófer de bus, acude a consulta por presentar dolor abdominal en hipocondrio derecho de 5 días de evolución, que se irradia hacia hombro y aumenta con inspiración profunda. Además, refiere alza térmica de 38.7ºC. de mismo tiempo de evolución. Niega viajes, uso de drogas intravenosas, limpiezas dentales o procedimientos invasivos recientes. Refiere como antecedentes, haber una apendicectomía a los 15 años. Al examen físico, el paciente se encuentra orientado en tres esferas, con TA: 120/75 mmHg, frecuencia cardíaca: 89 x minuto, FR: 14 x minuto, T: 38.5ºC, Sat O2 96%. Conjuntivas rosadas, escleras no ictéricas. Mucosas orales semi húmedas. Cardiopulmonar: sin datos patológicos. Abdomen: blando, depresible, doloroso a la palpación en hipocondrio derecho, puñopercusión hepática positiva, ruidos hidroaéreos presentes. No otros datos patológicos. Se realiza un eco abdominal, que reporta lesión única, redondeada, hipoecoica de márgenes regulares, en lóbulo derecho, de aproximadamente 4 cm de diámetro. ¿Cuál sería su tratamiento antibiótico de elección?",
