    "stem": "Un paciente masculino de 54 años, acude a su consulta por presentar dolor torácico sin causa aparente, de intensidad moderada con irradiación hacia mandíbula, brazo y hombro izquierdo. El dolor se acompaña de mareo que lo obliga a permanecer sentado. No hay antecedentes patológicos de importancia. Al examen físico la frecuencia cardiaca es de 162/min, FR: 19/min, T: 36.8 °C, TA: 100/82 mmHg, Sat de O2: 89% en aire ambiente. El paciente se encuentra inquieto, pálido, sudoroso y refiere que el dolor está aumentando. Hay presencia de murmullo vesicular bilateral. Se realiza un electrocardiograma de 12 derivaciones y se evidencia en V2 y V3 elevación del segmento ST. ¿Cuál sería el tratamiento inicial para este paciente mientras se espera la terapia de reperfusión mediante fibrinolíticos?",
