    "stem": "Mujer de 30 años, en su tercer mes de gestación, refiere prurito vulvovaginal y secreción blanquecina. En la especuloscopía se objetiva eritema, edema vaginal y abundante leucorrea blanca grumosa sin mal olor adherida a las paredes de la vagina y cuello uterino. ¿Cuál es el microorganismo responsable?",
