  {
    "id": "html-374",
    "subject": "Banco general de medicina",
    "stem": "Niña de 10 años, es llevada a consulta externa por un notable descenso del rendimiento escolar. En clase está ausente y en las horas de recreo tiende a alejarse de sus amigas e incluso se queda en el aula, según manifiesta su profesora. Su madre, con la que vive, indica que notó cambios cuando se divorció del padre de su hija, hace 2 meses, y desde allí la ve cada vez más irritable y susceptible, contesta de malos modos y no aguanta la más mínima crítica. Tiene dificultades para conciliar el sueño y ha perdido algo de apetito. ¿Cuál es el factor de riesgo psicológico más significativo para la niña?",
