    "stem": "Varón de 34 años, evaluado en el quirófano como donante de órganos. 6 horas antes de su ingreso sufre politraumatismo en accidente de tránsito, 30 minutos antes de su evaluación se declaró muerte cerebral. Niega antecedentes médicos de importancia. Examen físico: Tensión arterial 130/80 mmHg (sin soporte inotrópico), frecuencia cardíaca 90 latidos por minuto, frecuencia respiratoria 16 por minuto en ventilación mecánica, T 37 °C. ¿Cuál es el riesgo quirúrgico de ASA (American Society of Anesthesiologists) para este paciente?",
