  {
    "id": "html-378",
    "subject": "Banco general de medicina",
    "stem": "Se presenta un paciente de 10 años que es traído por su madre por presentar lesiones cutáneas recurrentes. La madre refiere que las lesiones aparecieron sin causa aparente hace tres semanas y han aumentado progresivamente, acompañándose de prurito intenso que empeora en la noche. Como único antecedente de relevancia se encuentra un diagnóstico de rinitis alérgica hace dos años, por lo que evita contacto con polen y otras fuentes partículas aéreas. Al examen físico se observan tres placas de características similares, localizadas en cuello, cara y dorso del pie derecho. Las placas son irregulares, mal definidas, de color eritematoso y presentan descamación fina sin presencia de cebo o secreción. La lesión del cuello llama la atención por encontrarse signos leves de liquenificación. No hay evidencia de lesiones satélite. ¿Cuál sería el tratamiento inicial más apropiado para este paciente?",
