    "stem": "Usted atiende a un paciente de 17 años que acude por presentar tos persistente. Refiere que ha presentado accesos de tos y rinorrea desde su infancia, atribuidos a rinitis alérgica por un pariente médico. Sin embargo, los accesos se han vuelto más frecuentes e intensos en los últimos años y se acompañan de esputo verdoso. Como antecedentes clínicos refiere múltiples episodios de sinusitis, en promedio uno o dos al año, y tres hospitalizaciones por neumonía en los últimos dos años. Como hallazgo relevante refiere también deposiciones pastosas, frecuentes y de mal olor desde que era niño, que empeoran con el consumo de lácteos o grasas. Los hallazgos relevantes del examen físico incluyen talla y peso bajos, notable congestión nasofaríngea y disminución del murmullo vesicular bilateral a la auscultación. ¿Cuál de las siguientes pruebas sería la más apropiada para confirmar el diagnóstico en este paciente?",
