    "stem": "Paciente masculino de 45 años, se realiza endoscopia alta como parte de un chequeo ejecutivo. Refiere leve malestar a nivel de epigastrio, con sensación de llenura y distensión abdominal postprandial. Su hábito evacuatorio no ha cambiado, niega pérdida de peso. Dentro de sus antecedentes personales: apendicectomía a los 12 años. Antecedentes familiares: abuela materna tuvo cáncer de útero a los 56 años. Al examen físico, sus signos vitales están estables. Cardiopulmonar: normal. Abdomen: blando, depresible, levemente doloroso a la palpación en epigastrio, ruidos normales. Se aprecia timpanismo generalizado, no visceromegalias. Resto del examen físico es normal. En la endoscopia, se encuentra una gastropatía eritematosa de antro, resto del examen es normal. Se recibe el resultado de la biopsia que indica: gastritis crónica con atrofia leve y metaplasia intestinal incompleta, Helicobacter pylori positivo. ¿Cuál sería su recomendación?",
