    "stem": "Una mujer de 38 años acude a consulta médica por cuadro de 6 horas de evolución de dolor de moderada intensidad (EVA 6/10) localizado en pierna derecha. Además, ha notado hinchazón y enrojecimiento en la misma pierna. Refiere haber realizado viaje de 10 horas de duración en autobús. Sus antecedentes personales incluyen aborto espontáneo por dos ocasiones, la etiología de los mismos fue síndrome antifosfolipídico; actualmente sin tratamiento. Toma anticonceptivos orales como método de planificación familiar. Al examen físico FC: 85/min, FR: 21/min, TA: 100 /65 mmHg, temperatura: 37.3 °C. La pierna derecha se encuentra con edema, la piel está enrojecida, caliente; hay incremento de dolor en la pantorrilla al realizar dorsiflexión del pie. Pulso pedio presente. El hemograma muestra leucocitos de 10500 /mm3 con 66 % de segmentados neutrófilos. La química sanguínea muestra glucosa de 120 mg/dl, creatinina 1.2 mg/dl, dímero D 700 µg/L. De acuerdo a su sospecha diagnóstica, la conducta terapéutica más adecuada sería:",
