    "stem": "Un hombre de 25 años, acude a su consulta por presentar desde hace 1 semana dolor pélvico ocasional de tipo cólico de leve intensidad, que se acompaña de ardor al orinar y escalofríos, el dolor se irradia hacia testículo izquierdo y región inguinal del mismo lado, empeora durante la deposición. Como antecedente el paciente tiene múltiples parejas sexuales. Al examen físico se encuentra una temperatura de 38 °C, TA: 120 /75 mmHg, FC: 98/min, FR: 18/min. Consciente, orientado, inquieto por el dolor, tórax y abdomen normales, presencia de ganglio palpable doloroso en región inguinal, testículo izquierdo doloroso a la palpación. En los exámenes de laboratorio hay leucocitosis marcada, el resto de exámenes son normales. Se realiza una biopsia con aguja fina que muestra un prominente infiltrado leucocitario con numerosos neutrófilos, en el cultivo de secreciones hay presencia de cocos gram-negativos. ¿Cuál de los siguientes organismos es la causa más probable de esta infección?",
