    "stem": "Hombre de 63 años, economista, residente en Quito, diestro de lateralidad. Hipertenso recibe irbesartan 300 mg al día. Hace 3 días presenta por primera vez malestar general, alza térmica no cuantificada, dolor abdominal y náusea. Hace 24 horas refiere cefalea fronto temporal izquierda, alcanza EVA 8/10, las hijas notan que el paciente por momentos tiene dificultad para comprender preguntas. En el trayecto al hospital presenta por primera vez una crisis focal motora derecha de dos minutos de duración. En emergencia la TA es de 145/95 mmHg, temperatura bucal de 38.8 °C, Fc 96 LPM, saturación de O2 (aire ambiente) 94%. El paciente está alerta, con un lenguaje fluente, comprende comandos simples y no comprende secuencia de órdenes verbales, hay dificultad para nombrar objetos y repetir frases. El fondo de ojo presenta edema papilar y el resto de pares craneales son normales. No hay déficit motor ni signos meníngeos. La biometría hemática muestra leucocitos 12.430mm3; 52% linfocitos. Proteína C reactiva de 7.3 mg/L. ¿Cuál es el diagnóstico más probable en este paciente?",
