    "stem": "Un hombre de 70 años es atendido en el hospital debido a intenso dolor abdominal y distensión. Había tenido dificultad para la micción durante las últimas semanas y finalmente no pudo orinar durante los dos últimos días. Al examinarlo se determina una vejiga palpable. El resto del examen no evidencia ningún hallazgo anormal. Se introduce una sonda urinaria y elimina 1500 cc de orina. Se pide un antígeno prostático específico que resulta normal. Su BUN: 89 mg/dl, creatinina: 6.4 mg/dl. En los siguientes cuatro días de hospitalización su BUN y creatinina descienden, pero sus volúmenes urinarios se incrementan. No está recibiendo ningún fluido intravenoso. Ha llegado a orinar hasta 6 litros diarios en las últimas 48 horas. ¿Cuál sería la complicación más probable que podría aparecer en este paciente?",
