    "id": "html-505",
    "subject": "Banco general de medicina",
    "stem": "Varón de 25 años acude a urgencias por alza térmica, ictericia y delirio posterior a estancia en clima tropical. El área de estancia es predominante para Aedes aegypti. No refiere antecedentes médicos de importancia; sin embargo, el familiar indica que no cumplió con el esquema de vacunación previo al ingreso a su área de trabajo. El cuadro inicia hace 72 horas con ictericia progresiva que se acompaña de hematemesis, anuria y delirio terminal. Al examen físico presenta: Ictericia generalizada, irritabilidad y signos de deshidratación. Tensión arterial de 90/60 mmHg, con ortostatismo positivo, temperatura 38.2° C, frecuencia cardíaca de 110 latidos por minuto, frecuencia respiratoria 18 respiraciones por minuto, Sat O2 aire ambiente 94%. Exploración cardiopulmonar normal. Neurológico: sin focalidad. ¿Cuál es el diagnóstico más probable de este paciente?",
