    "stem": "Paciente de 38 años, sometida a colecistectomía convencional de vías biliares hace 5 años, acude con masa tumoral en región abdominal que disminuye de tamaño con el reposo; le preocupa porque va aumentando de tamaño progresivamente. Al examen físico presenta: masa supraumbilical media de aproximadamente 15 cm de diámetro, blando, no doloroso, reductible; defecto aponeurótico de 7 cm de diámetro. Es diagnosticada de hernia incisional. Durante la evaluación preoperatorio el examen de sangre demuestra: hemoglobina (Hb) 6 g/L, hematocrito (Hcto) 24%, plaquetas 100 000, tiempo de protrombina (TP) 11 segundos, tiempo parcial de tromboplastina (TPT) 35 segundos. Como preparación para la cirugía, seleccione la decisión más acertada:",
