  {
    "id": "html-512",
    "subject": "Banco general de medicina",
    "stem": "Un escolar de 8 años, presenta desde hace 48 horas, fiebre alta, odinofagia, astenia, cefalea y anorexia. En las últimas horas aparece un exantema eritematoso, distribuido en todo el cuerpo, especialmente en la cara, tórax y abdomen. Al examen físico presenta fiebre de 38.7 °C, FC 110 x 1´. El exantema es intenso en las mejillas y sin embargo, a nivel peribucal se presenta una zona libre de eritema, más bien pálida y blanquecina. Se observa una coloración oscura en los pliegues de los codos y rodillas, así como una mayor pigmentación de los surcos palmares. Presenta también adenomegalias submaxilares, dolorosas a la palpación. Su lengua es de un rojo intenso, con aumento de la visibilidad de sus papilas. Indicar el diagnóstico, la etiología del proceso y el tratamiento más adecuado.",
    "options": [
