    "stem": "Recién nacido a término por parto céfalo-vaginal, sin complicaciones neonatales inmediatas. Peso= 2 200 g, Talla= 49 cm, PC= 35cm. El examen físico es normal. Si tiene un entorno favorable. ¿Cuál es el diagnóstico neonatal y su pronóstico?",
