    "id": "html-515",
    "subject": "Banco general de medicina",
    "stem": "Un varón de 23 años acude a consulta aquejando fiebre y dolor articular junto con hinchazón, desde hace una semana. El dolor y edema articular comenzó en sus rodillas. En los últimos tres días la molestia cesó en las rodillas y se instaló en su codo derecho y muñeca izquierda. Esto le ha impedido realizar sus actividades cotidianas. Un médico le prescribió diclofenaco, lo cual le alivió temporalmente el dolor articular. Adicionalmente, ha tenido fiebre y sudoración. Niega dolor faríngeo o fiebre en las semanas anteriores. Únicamente recuerda haber cursado con un episodio similar, 8 años antes. En aquel tiempo no fue evaluado por ningún médico. El cuadro clínico remitió espontáneamente. Actualmente no se acompaña de disnea o dolor torácico. Al examen se ve en regulares condiciones. Temperatura: 38,5 °C, TA: 120/70 mmHg, FC: 90 x min, FR: 20 x min. ¿Cuál es el examen complementario que apoyaría su sospecha diagnóstica de un síndrome inflamatorio post infeccioso?",
