  {
    "id": "html-516",
    "subject": "Banco general de medicina",
    "stem": "En relación con la nefrotoxicidad producida por fármacos. ¿Cuál es el enunciado correcto?",
    "options": [
      "Los aminoglucósidos son antibióticos con alto potencial nefrotóxico, el cual ocurre sobre todo en adultos mayores y esto se asocia a necrosis tubular aguda.",
