  {
    "id": "html-517",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 44 años padece cefaleas episódicas de media hora de duración, asociadas a sudoración profusa, palpitaciones y sentimientos de aprehensión, en los últimos tres meses. Ha perdido peso (unas 15 libras) a pesar de que su apetito se mantiene normal. Manifiesta que no tiene razones para estresarse. Lleva una vida tranquila. Por lo general maneja bien sus preocupaciones. Niega insomnio. Solamente toma ibuprofeno para el dolor, aunque normalmente ceden espontáneamente. Mantiene sus menstruaciones. No refiere sensaciones de calor o enrojecimiento facial. Durante un episodio se realiza el examen físico, el cual muestra: TA: 150/100 mmHg (acostada), 130/80 mmHg (en pie), FC (acostada): 112 lpm y sentada: 136 lpm. Auscultación cardíaca: latido rítmico, sin soplos; abdomen: no visceromegalias ni soplos. Examen neurológico: normal. ¿Cuál sería el diagnóstico más probable en el caso descrito?",
