    "id": "html-518",
    "subject": "Banco general de medicina",
    "stem": "Un hombre de 51 años, sin antecedentes patológicos personales, sin historial de tabaquismo, bebedor social, sin ingestión de medicamentos, es derivado a hematología debido al hallazgo incidental de un hematocrito elevado. Se había realizado un examen a causa de una herida que accidentalmente se produjo mientras realizaba un trabajo de reparación en casa. Los resultados mostraban: Hto. 59 %, Hb: 20 g/dl, Leucocitos: 15.400 x mm3 con una fórmula diferencial normal, plaquetas: 445.000 x mm3. Al examen físico su TA: 145/85 mm Hg, FC: 85 x min, FR: 18 x min, SatO2: 95 % al aire ambiente. Se identifica una esplenomegalia grado II. La última vez que fue evaluado por un médico fue hace unos 3 años; por aquel entonces no recuerda que sus resultados de laboratorio fueran anormales. ¿Cuál sería el siguiente mejor paso en el trabajo diagnóstico de este paciente?",
