  {
    "id": "html-525",
    "subject": "Banco general de medicina",
    "stem": "Paciente de 55 años acude a la consulta por presentar disuria, dolor lumbar y fiebre de aproximadamente de 8 días de evolución. Signos vitales: TA: 130/90 mmHg, FC: 90 LPM, FR: 18 RPM, T: 39 °C. En la ecografía se encontraron los siguientes hallazgos: aumento de tamaño de la próstata, asimetría de los lóbulos prostáticos, incremento del diámetro de los plexos venosos periprostáticos, nódulos hiperecogénicos en la próstata externa, evidencia de litiasis intraprostática, presencia de halos hipoecoicos periuretrales o calcificaciones entre la zona transicional y la cápsula. Basados en la clínica y la ecografía. ¿Cuál es el probable diagnóstico?",
