    "stem": "Se presenta el caso de un paciente de 38 años que acude por insomnio de conciliación, tristeza generalizada, anhedonia y abulia de tres meses de evolución. Durante la anamnesis se identifican también importantes preocupaciones sobre el futuro, ligera agitación psicomotriz, impulsividad e irritabilidad. El paciente no tiene antecedentes patológicos de importancia, pero refiere cuatro episodios similares en el pasado, ninguno de los cuales recibió atención médica. ¿Cuál sería el tipo de depresión mayor más probable en este caso?",
