    "stem": "Gestante de 28 años primigesta, acude al control prenatal a las 10 semanas de gestación. Refiere ausencia de síntomas de embarazo desde hace una semana. Niega dolor pélvico o sangrado genital. Al examen físico presenta: TA de 120/70 mmHg; FC 85/minuto; T 36 °C, el abdomen es suave depresible, no doloroso a la palpación, la altura del fondo uterino no es palpable. Al examen especular no se evidencia sangrado genital. Al tacto vaginal el eje uterino está en anteverso flexión, consistencia reblandecida, un tamaño aproximado de 1.2x, no doloroso a la movilización; el cérvix es posterior de consistencia dura, con el orificio cervical externo cerrado; los anexos no son palpables. ¿Cuál es el diagnóstico inicial más probable?",
