    "stem": "Niño de 4 años es llevado a consulta por presentar fiebre de 38 °C desde hace 2 días acompañada de rinorrea y tos. Al examen físico tenemos paciente febril con astenia pero que responde a estímulos; en la boca se observan unas manchas pequeñas de color rojo con una base de coloración azul grisáceo; también rash maculopapular que a la digitopresión desaparece en la cara; el resto del examen es normal. Madre refiere que tiene en casa una hija de 10 meses de edad y que luego de una reacción adversa a la vacuna de la influenza, ella y su esposo decidieron no administrar vacunas a sus hijos. ¿Cuál vacuna debe ser administrada a la hermana de 10 meses inmediatamente?",
