    "stem": "Paciente femenina de 23 años, residente en zona subtropical, acude a consulta por presentar fiebre continua desde hace 7 días, con astenia, mialgias y artralgias, malestar general y dolor abdominal difuso de moderada intensidad. Además, refiere cefalea que es intensa, en región frontal. No refiere antecedentes de importancia. Al examen físico, TA: 120/75 mmHg, frecuencia cardíaca: 86 x min, frecuencia respiratoria: 14 x min, T:38.6ºC, sat O2: 93%. A nivel de piel, se evidencia la presencia de rash eritematoso generalizado. Conjuntivas eritematosas, escleras normales. Mucosas orales semi húmedas y orofaringe eritematosa. Cardiopulmonar: no se revelan datos patológicos. Abdomen: blando, levemente doloroso a la palpación de forma difusa, se evidencia hepatomegalia dolorosa a la percusión, sin esplenomegalia. Se realizan exámenes de laboratorio: leucocitos 12.000 /uL, neutrófilos 78%, plaquetas 120.000 x ml, hematocrito 45%, creatinina 1.3 mg/dL, sodio 142 mEq/L, potasio 3.1 mEq/L, AST 84 UI/L, ALT 93 UI/L. Se descarta dengue, chikungunya, paludismo y malaria. Usted tiene la sospecha clínica de leptospirosis. ¿Qué tratamiento iniciaría en base a su sospecha diagnóstica?",
