    "stem": "Un paciente de 22 años, presentó faringoamigdalitis estreptocócica hace 3 semanas. Desde hace 10 días tiene fiebre alta, decaimiento, malestar general, irritabilidad, movimientos involuntarios, alteraciones del carácter, odinofagia y disfagia. Refiere también dolor e hinchazón en diversas articulaciones. Actualmente presenta congestión amigdalina, con exudado purulento y petequias en paladar; adenopatías submaxilares y latero-cervicales marcadas y dolorosas a la palpación; fiebre alta y en ciertas partes, exantema escarlatiniforme. Presenta leucocitosis y niveles de PCR 4 veces por encima de lo normal. ¿Cuál de las siguientes alternativas permite establecer el diagnóstico de fiebre reumática?",
