    "stem": "Una mujer de 20 años es llevada al servicio de emergencias por cuadro de 1 hora de evolución de alteración del estado de conciencia, dificultad respiratoria y desmayo; familiar refiere como causa aparente ingesta de pastel de mariscos. Sus antecedentes patológicos familiares incluyen alergia conocida a los crustáceos diagnosticada hace 8 años. Al examen físico FC: 145/min, FR: 35/min, TA: 88/39 mmHg, SO2: 75 %. En la cara edema palpebral bilateral, edema de los labios y la lengua, no responde a estímulos verbales. Cianosis en lechos ungueales, importante dificultad respiratoria. Se coloca al paciente en posición supina con elevación de sus extremidades inferiores, se coloca dos vías intravenosas periféricas, se inicia reanimación hídrica y se realiza intubación orotraqueal. ¿Cuál es la medicación inmediata más adecuada para la paciente?",
