    "stem": "Seleccione el planteamiento correcto con relación a las hemorroides: 1. La escleroterapia está indicada en todos los grados de hemorroides. 2. En las hemorroides combinadas grandes y sintomáticas se realiza hemorroidectomía. 3. En las hemorroides postparto el tratamiento de elección es la escleroterapia. 4. Las hemorroides externas están recubiertas con anodermo y pueden causar prurito. 5. Son más frecuentes en pacientes con hipertensión portal que en la población normal. 6. Las hemorroides internas están cubiertas por mucosa anorrectal insensible.",
