    "stem": "Hombre de 58 años, acude a consulta por dolor intermitente en cuadrante superior derecho de abdomen, disnea de esfuerzo NYHA 3 y edema de miembros inferiores, de 3 meses de evolución. Antecedentes: Infarto miocárdico de cara anterior extenso. Examen físico: TA: 100/60 mmHg, FC: 84 lpm, FR: 20 rpm. Cuello: ingurgitación yugular. Tórax: murmullo vesicular conservado, estertores crepitantes en bases pulmonares. Abdomen: depresible, se palpa hepatomegalia dolorosa 2cm por debajo de reborde costal derecho, onda ascítica positiva. Extremidades: edemas pretibiales duros no dejan fóvea xx/xxx. En complementarios se evidencia: ALT 112 U/L, AST 78 U/L, FA 150 U/L, GGT 90 U/L. Ecografía doppler portal informa elevación del gradiente de presión venosa hepática en 9 mmHg. ¿Cuál de los siguientes es la causa más probable de hipertensión portal en el paciente?",
