    "stem": "Hombre de 25 años es llevado a emergencias por personal del ECU 911, porque hace 1 hora sufre traumatismo penetrante con arma blanca en la columna cervical. Antecedentes: sin importancia. Al examen físico: Consciente y orientado en las tres esferas. TA: 110/75 mmHg, FC:90/min, FR:20/min. SatO2 aire ambiente 94%. Columna vertebral: herida penetrante en la región paravertebral derecha a nivel de la séptima vértebra cervical. Neurológico: hemiparesia derecha de predominio crural con alteración de la sensibilidad profunda y vibratoria del mismo lado y una sensación de dolor y temperatura disminuida en el lado izquierdo a partir del nivel medular T1. ¿Cuál es el síndrome que presenta el paciente?",
