    "stem": "Una mujer de 55 años acude a consulta de dermatología por presentar un lunar en su brazo izquierdo que ha crecido y le produce picazón. Sin antecedentes personales de importancia. Al examen físico: FC: 87/min, FR: 18/min, TA: 100/65 mmHg. A la exploración presenta en la cara lateral de su brazo izquierdo un lunar de color marrón oscuro, de 7 mm de diámetro, nodular y redondo de forma irregular. No hay ulceración ni sangrado. ¿Cuál es el manejo más apropiado de este lunar?",
