    "stem": "Una mujer de 28 años acude a consulta de ginecología por dolor en las relaciones sexuales. Además, ha presentado sangrados vaginales entre las menstruaciones. Sus antecedentes ginecológicos incluyen menarca a los 15 años, ciclos menstruales regulares cada 28 días, vida sexual activa, con una nueva pareja hace 1 mes. Su método de planificación familiar es el uso de anticonceptivos orales, nunca ha estado embarazada. Al examen físico: TA: 110/67 mmHg, FC: 67/min, FR: 18/min, temperatura 36.2 °C. En la especuloscopía vaginal se observa secreción endocervical purulenta visible en el canal endocervical, se produce pequeña hemorragia con el paso de hisopo a través del orificio cervical. ¿Cuál de las siguientes es la farmacoterapia más adecuada para la paciente?",
