    "id": "html-613",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 24 años, nulípara, acude a consulta por presentar secreción vaginal desde hace 3 días que aumenta en cantidad luego del coito. Niega otros síntomas acompañantes. Inicio de la actividad sexual a los 20 años con una sola pareja sexual y utiliza anticoncepción oral desde hace 3 años. Al examen físico presenta: signos vitales normales. Genitales: leucorrea grisácea fétida en moderada cantidad, vagina y cérvix sin anomalías. Resto de la exploración normal. La preparación en fresco de la secreción vaginal muestra células guía al microscopio, el pH vaginal es de 6 y la prueba de aminas es positiva. ¿Cuál es el diagnóstico de la paciente?",
