    "stem": "Paciente de 3 años asiste a hospital de segundo nivel básico, con estridor inspiratorio y entrada de aire muy limitada. Al examen físico se observa un paciente somnoliento, letárgico, con retracciones torácicas generalizadas, cianosis distal, SpO2 menor a 90 %. FR: 60 rpm, FC 120 lpm. Seleccione la combinación correcta en cuanto a las medidas iniciales y fármacos en el crup:",
