    "stem": "Varón de 15 años, residente en la zona rural. Presenta fiebre y escalofríos de 15 días de evolución y la aparición de dos masas dolorosas a nivel inguinal. El paciente niega síntomas urinarios, comenta haber tenido contacto sexual sin protección. En la consulta, TA 110/70 mm Hg, 80 LPM, 37.5°C temperatura bucal, peso 50 kg. Se observa dos masas no ulceradas a nivel inguinal y femoral, de 4 x 5 centímetros, de consistencia firme y móviles y 2 lesiones ulcerosas en fase de resolución en el dorso del pene. Leucocitos 15 100/mm3 (61% neutrófilos), VSG 17 mm/hora. VDRL negativo. El estudio histopatológico de las lesiones inguinales es positivo para linfogranuloma venéreo. ¿Cuál de los siguientes fármacos es el de primera elección?",
