    "stem": "Una mujer de 65 años asiste con su hijo a una consulta de neurología a causa de pérdida de la memoria durante el último año. Su hijo dice que hace una semana, durante un paseo su madre no recordaba el camino de regreso, aunque estaba a solo una cuadra de la casa. Sus antecedentes familiares incluyen hermana mayor con demencia. Niega uso de drogas o alcohol. Al examen físico TA: 130/80 mmHg, FC: 87 /min, FR: 20/min, temperatura 36.5 °C. Está orientada en tiempo, espacio y persona. Es capaz de recordar eventos pasados bastante bien, pero su memoria reciente está deteriorada. Tiene dificultad para recordar los nombres de los objetos comunes. ¿Cuál es el tratamiento más adecuado para esta paciente?",
