    "stem": "Un paciente de 55 años sufre un accidente de tránsito. Es trasladado en ambulancia al servicio de emergencia de un hospital. Luego de la evaluación se determina que tuvo un trauma abdominal. Ingresa a quirófano inmediatamente, se repara la lesión intraabdominal. Su estado clínico se estabiliza. Sin embargo, en su segundo día de hospitalización, el paciente sufre una súbita caída en su presión arterial. Se conoce que el paciente tomaba corticoides por largo tiempo. La nueva evaluación no encuentra indicios de sangrado. Su TA está en 90/60 mm Hg, FC: 110 lpm, FR: 18 x min, SatO2: 92%, T: 38.5 °C. Los exámenes de laboratorio reportan: hiperpotasemia, hiponatremia, hipoglucemia, eosinofilia. La hemoglobina está en 13 g/dl. ¿Cuál sería el próximo paso más apropiado en el manejo de este paciente?",
