    "stem": "Una Mujer de 30 años, cursa embarazo de 36 semanas de gestación y acude a consulta por presentar flujo vaginal abundante, blanquecino, sin mal olor, que moja su interior. Niega síntomas irritativos, niega disuria. No tiene antecedentes personales de importancia. Antecedentes obstétricos: Gesta 1 Paridad 0. Al examen físico de la región inguino genital: vestíbulo vaginal sin secreciones, al examen especular paredes vaginales violáceas, presencia de flujo abundante, blanco, espeso, homogéneo, no adherido a paredes vaginales. El cérvix tiene aspecto macroscópico normal, de color violáceo, no se visualiza salida de líquido por orifico cervical externo, ni con maniobra de Valsalva. La medición del PH vaginal con papel de nitrazina es de 4. Cristalografía en acúmulos, ¿Cuál es el diagnóstico más probable?",
