    "stem": "Una mujer de 66 años es trasladada por su hija mayor a la emergencia de un hospital debido a un cuadro de lipotimia. Al interrogarla, se conoce que en las últimas 24 horas experimentó varias deposiciones de color rojo negruzco en cantidad moderada. No ha tenido cuadros similares en el pasado. Entre sus antecedentes personales patológicos refiere hipertensión arterial, la cual se trata con hidroclorotiazida. Al examen físico resalta su TA: 94/62 mmHg, FC: 115 lpm, piel pálida. Su estado mental es normal. No hay otros hallazgos de importancia. Ante este cuadro clínico. ¿Cuál considera el próximo paso más apropiado para el manejo de esta paciente?",
