    "stem": "Hombre de 32 años, acude a consulta por tumoraciones en cuello y axilas, sudoración nocturna, pérdida de peso, de 3 semanas de evolución. Examen físico: TA 120/80 mmHg, FC: 89 lpm, FR: 18 RPM. Cuello se palpa adenopatías no dolorosas de consistencia elástica en cadenas ganglionares cervicales laterales y posteriores bilaterales. Regiones axilares bilaterales se palpan adenopatías de similares características. Abdomen: depresible, no doloroso, no se palpa visceromegalias. Exámenes de laboratorio LDH 450 U/L. ¿Cuál de los siguientes es el diagnóstico más probable?",
