    "stem": "Un niño de 1 mes de vida es llevado a consulta con su pediatra por cuadro de 1 semana de evolución de vómito, inició con vómitos postprandiales no biliosos, de contenido lácteo; posteriormente los vómitos fueron más frecuentes y hace 24 horas son explosivos después de cada alimentación. El niño conserva el apetito y llora de hambre. No ha presentado deposiciones diarreicas ni alza térmica. Sus antecedentes natales incluyen parto vaginal espontáneo a las 39 semanas, sus puntajes de Apgar fueron 7 al primer minuto y 9 a los 5 minutos. Al examen físico FC: 135/min, FR: 28 /min, TA: 70/50 mmHg, temperatura: 36,9 °C. El tórax es expansible con murmullo vesicular conservado, el abdomen con distensión moderada en hemiabdomen superior, a la palpación profunda se palpa tumoración esférica de 1cm en epigastrio. La radiografía de abdomen muestra dilatación gástrica con escaso gas en asas intestinales distales. ¿Cuál es el diagnóstico más probable?",
