    "stem": "Una mujer de 50 años acude al servicio de urgencias con dolor en el dedo gordo del pie izquierdo que hace doloroso el solo apoyar el pie, no tiene antecedentes de traumatismo a ese nivel. Refiere haber comido una parillada y haber bebido cerveza la noche anterior. El dolor comenzó hace 6 horas y está empeorando progresivamente. Sus antecedentes personales incluyen úlcera péptica sin tratamiento específico al momento. El examen físico: TA 125/80 mmHg, FC:77/min, FR:20/min, temperatura 37°C. La primera articulación metatarsofalángica del pie izquierdo está inflamada, caliente y eritematosa. Es muy sensible a la palpación y hay disminución del movimiento. ¿Qué medicación es la más indicada en este paciente para su cuadro agudo?",
