    "stem": "Un paciente de 45 años, diestro de lateralidad, sufre una caída mientras conducía su moto sin portar casco; sufre un impacto directo en la región temporal derecha y permanece inconsciente en la calzada por 10 minutos. La evaluación en emergencia revela TA: 140/90 mmHg, Fc: 84 LPM, Fr: 16 por minuto, T: 37 °C, el paciente esta desorientado en espacio y tiempo, hay otorragia derecha, las pupilas son isocóricas de 2 mm de diámetro, no hay déficit motor, ni signos meníngeos. Una TAC simple de cráneo revela una fractura a nivel del hueso temporal derecho y un hematoma agudo subdural laminar frontal izquierdo sin efecto de masa sobre el parénquima cerebral adyacente. ¿Cuál de los siguientes pares craneales del lado derecho se encontraría afectado en este paciente?",
