    "stem": "Mujer de 50 años, acude a su consulta por debilidad intensa, fatiga y pérdida de peso desde hace 1 semana, acompañado de náusea en las mañanas que no llega al vómito. Antecedentes personales: artritis reumatoidea en tratamiento con prednisona 20 mg /día por 4 meses, metrotexato 15 mg semanal, medicación que suspende por decisión propia hace 1 semana. Al examen físico presenta: TA: 80/50 mmHg, FC: 90/min, FR: 20/min, SatO2: 94% en aire ambiente. T: 36.5 °C. Se objetiva mucosas orales secas, sudoración excesiva en la cara y en las palmas, resto de la exploración normal. La analítica sanguínea muestra: hemograma normal, glucosa 65 mg/dl, cortisol am 3.5 mcg/dl (5 a 25 mcg/dL); TSH: 2.35 mUI/L (0.37 y 4.7 mUI/L); T4L: 1.5 ng/dl. (0.9 a 2.3 ng/dL). ¿Cuál es el diagnóstico más probable?",
