    "stem": "Un escolar de 11 años acude a la consulta por presentar edema palpebral moderado, cefalea y astenia. Su madre refiere que la orina es de color rojizo. Al examen físico, el paciente está algo pálido y a nivel regional se observa un discreto edema bi-maleolar. Los signos vitales al momento son: FC: 72 x 1´; FR: 28 x 1´; TA: 130/90. Al indagar a fondo sobre la historia del paciente, su madre refiere que hace dos semanas aproximadamente presentó sintomatología compatible con la escabiosis, proceso que le generó algunas lesiones supurativas, que han disminuido luego de baños con agua de matico. El examen de orina demuestra la presencia de piocitos 5-6 por campo, innumerables hematíes dismórficos por campo, presencia de cilindros hialinos y una densidad normal. Los resultados del examen de sangre regresan con la novedad de tener la fracción C3 del complemento disminuida mientras que la albúmina plasmática esta en 4.5 g/dl. Con este cuadro. ¿Cuál es el diagnóstico más probable?",
