    "stem": "Varón de 35 años es traído a emergencias por nivel de conciencia alterado (Glasgow: 3 /15: O1 V1 M1), otorragia derecha y vómito. Requiere de asistencia inmediata para asegurar la vía aérea, pero el paciente presenta una vía aérea difícil y el procedimiento requiere de dispositivos avanzados. ¿Cuál es la conducta más apropiada para manejar al paciente, si usted no tiene destreza y práctica en intubación orotraqueal?",
