    "stem": "Un paciente varón de 40 años acude a la consulta por cuadro de insomnio con despertares reiterados, cansancio y cefalea de varios meses de evolución. Al examen físico: TA: 120/70, frecuencia cardíaca: 68 por minuto, Sat O2: 96%, T: 36.6°C. No se evidencia ningún dato patológico en el examen. Se realizan exámenes de laboratorio, en los que se encuentra: Leucocitos 5800 x 10 9/L, neutrófilos 65%, hematocrito 48%, glucosa 103 mg/dL, TSH 6,8 mU/L, fT4 0.5 ng/dL y anticuerpos antitiroglobulina: 6 UI/mL. ¿Cuál sería su sospecha diagnóstica?",
