    "id": "html-670",
    "subject": "Banco general de medicina",
    "stem": "Un hombre de 55 años acude a servicio de emergencia a causa de hormigueos alrededor de los labios y en las manos, de 1 día de evolución. Refiere que ha presentado diarreas acuosas en número de 10, durante 3 días y náuseas severas que no le permite ingerir alimentos. Sus antecedentes personales incluyen ingesta de bebidas alcohólicas hasta la embriaguez, dos veces por semana, desde los 45 años. Al examen físico TA: 125/75 mmHg, FC: 70/min, FR:18/min, temperatura 37.2 °C. Presenta espasmos faciales a la percusión del nervio facial justo en la zona anterior al trago de la oreja, inducción de espasmo carpiano después de inflar un brazalete de presión arterial en su brazo. ¿Cuál de las siguientes anomalías electrolíticas es probable que haya causado estos hallazgos?",
