    "stem": "Paciente de 25 años, primigesta de 35 semanas, residente en Quito, sin antecedentes de interés y asintomática. Acude al control prenatal con resultados de exámenes que muestran: Hb 12.5 g/dL, Hto 36.8 %, VCM: 86 fL, leucocitos 14.220, neutrófilos 58 %, linfocitos 35 %, eosinófilos 3 %, monocitos 2 %, basófilos 2 %, plaquetas 135.000 /ul, glucosa 91mg/dL, creatinina 0.7 mg/dL. Aporta analítica de control de hace 11 meses con Hb13.2 g/dL, Hto 41 %, VCM: 88 fL, leucocitos 7200, neutrófilos 64 %, linfocitos 31 %, eosinófilos 2 %, monocitos 2 %, basófilos 1 %, plaquetas 189.000/ul. ¿Cuáles son los cambios hematológicos en la analítica sanguínea durante el embarazo?",
