    "stem": "Una recién nacida prematura recibe atención urgente por distensión abdominal al séptimo día de vida; su madre refiere que está muy decaída, no responde a estímulos y no lacta. Ha presentado deposiciones verdosas por dos ocasiones. Sus antecedentes personales incluyen nacimiento por cesárea a las 34 semanas de gestación por preeclampsia en la madre, peso al nacer 2200 g. Al examen físico FC: 160/min FR: 50 /min TA: 60/40 mmHg, temperatura: 36 °C. El abdomen se encuentra distendido, ruidos hidroaéreos disminuidos. El hemograma muestra leucocitos 12000/mm3 con 88 % de segmentados neutrófilos. Prueba de sangre oculta en heces positiva. La radiografía de abdomen muestra burbujas de gas dentro de la pared intestinal. ¿Cuál es el diagnóstico probable de la paciente?",
