    "stem": "A su consulta acude una niña de 6 años por presentar dolor moderado de oído derecho de 24 horas de evolución, se encuentra afebril. Al examen otoscópico neumático del oído derecho se evidencia un eritema leve de la membrana timpánica con abombamiento leve de la misma; además se evidencia líquido y niveles hidro- aéreos detrás de la membrana timpánica. ¿Cuál es el diagnóstico correcto?",
