    "stem": "Paciente femenina de 42 años con diagnóstico de cáncer de mama, se encuentra en tratamiento luego de una mastectomía radical con quimioterapia por ganglio centinela positivo. Finaliza hace 6 días su 4to ciclo con 5FU, metotrexato y ciclofosfamida. Presentó inicialmente sequedad en la boca después de 3 días, y actualmente presenta dolor intenso y dificultad para alimentarse: tolera líquidos, pero tiene dificultad para tragar sólidos. Al examen físico, presenta signos vitales estables, con temperatura de 37.6 °C. ¿Qué esperaría encontrar al examen físico en la orofaringe?",
