    "stem": "Una mujer de 35 años cursando embarazo de 39 semanas, acude a emergencia con dolor abdominal tipo contracción uterina de tres horas de evolución, que se intensifica desde hace 1 hora, se acompaña de expulsión de tapón mucoso y sensación de pujo. Como antecedentes de importancia tiene diabetes gestacional, diagnosticada a las 28 semanas, controlada con dieta y ejercicio. Antecedentes obstétricos: G2, P1. Al examen físico: Peso 70 kg; Talla 1.65 m; TA 100/70 mmHg; abdomen gestante, altura del fondo uterino en epigastrio, feto en presentación cefálica, dorso izquierdo FCF 134 latidos/min. Actividad uterina 3 contracciones en 10 minutos. En la región inguino genital: cabeza fetal en piso pélvico. Se atiende el parto céfalo vaginal, posterior al nacimiento de la cabeza, la rotación externa no se completa por una impactación del hombro anterior fetal en la sínfisis del pubis de la madre. ¿Cuál de las siguientes intervenciones es la más adecuada a realizar en este momento?",
