  {
    "id": "html-686",
    "subject": "Banco general de medicina",
    "stem": "Un niño de 6 años, que vive en una región tropical del país, acude a consulta porque en los últimos 10 días presenta tos y esputo sanguinolento. Además, dolor abdominal ocasional, así como deposiciones diarreicas abundantes y con moco, que se producen por temporadas, desde hace un año. Ocasionalmente presenta también vómitos. En este año, por tres ocasiones presentó lesiones irregulares, longilíneas, a manera de trayectos indurados, eritematosos y pruriginosos en tórax, abdomen, glúteos y miembros inferiores. Estas lesiones desaparecieron en uno o dos días. Su peso es 15kilos (-2 DS para la edad). Su talla en el percentil 10. La biometría hemática reporta únicamente una marcada eosinofilia, con 600 eosinófilos/ml de sangre. Se realiza un coproparasitario que reporta la presencia de larvas parasitarias. Seleccionar el literal que contenga el parásito más probable de acuerdo con el cuadro clínico de este niño, y el medicamento con el que debería realizarse el tratamiento:",
