    "stem": "Varón de 45 años, presenta desde hace 3 meses dolor y sensación urente en las plantas de pies y hormigueo en las pantorrillas; ocasionalmente, hay sensación de hormigueo en las manos. El paciente está en tratamiento por tuberculosis meníngea desde hace 5 meses y completó la primera fase de tratamiento con isoniazida, rifampicina, pirazinamida, etambutol y prednisona. Desde hace 3 meses recibe diariamente isoniazida, rifampicina y prednisona (5 mg). Las pruebas para VIH y sífilis fueron negativas. Los signos vitales son normales, IMC 17 kg/m2, Glasgow 15/15, pares craneales normales. Hay arreflexia aquiliana bilateral, hipoestesia en bota bilateral, disminución de la sensibilidad vibratoria en ambas piernas y paresia distal de 4+/5 en los miembros inferiores. Glucosa basal 118 mg/dl, pruebas de función hepática son normales. La electromiografía mostró una polineuropatía sensitiva axonal en miembros inferiores. ¿Cuál de los siguientes fármacos puede producir polineuropatía en este paciente?",
