    "stem": "Una paciente mujer de 5 años, sin antecedentes patológicos personales ni familiares de importancia, es traída al consultorio por su madre por fiebre intermitente de 6 semanas de evolución (38-39 grados centígrados). La fiebre se acompaña de decaimiento y fatiga. Al examen físico se identifica adenopatías múltiples generalizadas, bilaterales, no dolorosas a la palpación, mayores a 2 centímetros de diámetro, no adheridas a planos profundos, hepatomegalia, palidez generalizada, sin signos de respuesta inflamatoria sistémica. La biometría hemática revela: leucocitos 3000/mm3, neutrófilos 1000/mm3, hemoglobina 7 gr/dl (con anemia normocítica normocrómica), plaquetas 80.000/mm3 y presencia de linfoblastos. ¿Qué otros exámenes de laboratorio son los más importantes a realizar en este momento para su diagnóstico?",
