    "stem": "Mujer de 58 años, acude a consulta por aumento de la consistencia fecal (heces Bristol tipo 1 - 2), frecuencia deposicional cada 72 horas, de 6 meses de evolución, para lo cual ha incrementado la ingesta de agua y fibra de origen natural, sin resultados favorables. Antecedentes: Hipotiroidismo. Examen físico: TA: 110/70 mmHg, FC: 74 lpm, FR: 27 rpm. Abdomen: depresible, no doloroso, no masas palpables. Región anorrectal: Esfínter anal tónico, ampolla rectal ocupada por heces semisólidas. Resto de examen físico normal. Se realiza Manometría anorrectal que registra tono en reposo medio del esfínter anal y presión de contracción en valores normales. ¿Cuál es el tratamiento más adecuado?",
