    "id": "html-737",
    "subject": "Banco general de medicina",
    "stem": "Hombre de 68 años acude a emergencias porque desde hace 8 horas presenta dolor en hipogastrio e incapacidad para orinar. Niega otros síntomas del tracto urinario inferior. Antecedentes: neoplasia de vejiga en tratamiento con radioterapia, última sesión hace 24 horas. Al examen físico presenta: TA: 120/70 mmHg, FC: 74 lpm, FR: 18 rpm, T: 36ºC. Abdomen: RHA presentes, dolor a la palpación en región suprapúbica, con evidencia de plenitud y sensibilidad a la percusión. No signos de irritación peritoneal. Resto de la exploración normal. Se coloca de inmediato un catéter uretral sin presentar resistencia cercana al meato ni otra dificultad durante el procedimiento, donde se objetiva orina hematúrica con coágulos y se deja conectada sonda 20Fr de tres vías para irrigación vesical continua. ¿Cuál es la causa más probable del cuadro que presenta el paciente?",
