    "id": "html-738",
    "subject": "Banco general de medicina",
    "stem": "Un varón de 28 años consulta por marcada falta de aire y palpitaciones al menor esfuerzo físico, de 3 años de duración, junto con permanente presencia de mareos y sensación de “caminar en las nubes” o de “tener la cabeza vacía”. Ha recurrido a varios especialistas sin resultados y en ese lapso se le realizaron estudios cardiológicos, neurológicos y neumonológicos, con resultados normales. Al examen aparece ansioso, con frecuentes suspiros y, frecuencia cardíaca regular de 110 lat/min. Al tomar la TA -120/80 mmHg, refiere hormigueos en la mano del brazo explorado, con contractura en forma de “mano de partero”. ¿Cuál es el diagnóstico etiológico más probable?",
