    "stem": "Gestante de 29 semanas por FUM, con IMC de 18.5 kg/m2 y antecedente de tabaquismo. La ecografía del primer trimestre correlaciona la edad gestacional con la FUM. La ecografía actual objetiva 25 semanas de edad gestacional e índice de líquido amniótico (AFI) 4 cm. A la exploración física 22 cm de altura uterina. ¿Qué criterio se relaciona con restricción del crecimiento intrauterino?",
