    "stem": "Niño de 8 meses de edad es llevado a consulta externa por su madre por presentar erupción rojiza en la piel, que evolucionó de arriba hacia abajo, desde la cara hacia la parte superior del cuello, el pecho, los brazos y las piernas, llegando hasta la palma de las manos y plantas de los pies. Días previos presentó fiebre 39 °C, tos intensa, catarro y congestión ocular. Antecedentes personales: esquema de vacunación completo para la edad. Al examen físico: frecuencia cardíaca 114 por minuto, frecuencia respiratoria 34 por minuto, temperatura 37.8 °C. Erupción maculopapulosa, rojiza, no vesicular en cara y cuerpo, de progresión cefalocaudal. No presenta adenopatías. ¿Cuál es el agente causal más probable?",
