    "id": "html-743",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 48 años es trasladada al servicio de emergencia a causa de dolor torácico que empezó unos 40 minutos antes, inmediatamente luego de cenar. El dolor se incrementó progresivamente en intensidad hasta llegar a ser 9/10, de carácter urente, asociado a un sabor ácido en su boca. Además, se acompaña de náusea, sudoración fría y sensación de muerte inminente. Ha experimentado eventos similares, pero nunca tan intensos como el actual. Está muy preocupada pues piensa que está teniendo un ataque cardíaco. Previamente, el dolor había aliviado con tabletas de carbonato de calcio. No tiene historial de enfermedades cardíacas ni otros problemas de salud. No toma medicamentos. No fuma, no ingiere alcohol ni usa drogas ilícitas. Al examen: TA: 125/70 mm Hg, FC: 78 x min, FR: 18 x min, SatO2: 93 %, el resto de la exploración física es normal. Sus exámenes de laboratorio iniciales son normales al igual que un ECG. Se administra nitroglicerina sublingual y sorpresivamente el dolor cesa. ¿Cuál de los siguientes diagnósticos diferenciales es el más probable en esta paciente?",
