    "stem": "Paciente de 22 años, con 9 semanas de gestación, sin antecedentes de interés. Refiere que desde hace 2 semanas presenta astenia sin otros síntomas acompañantes, en la analítica se objetiva: Hb 10.6 g/dL, Hto 31 %, VCM: 83 fL, leucocitos 13 250, neutrófilos 58 %, linfocitos 35 %, eosinófilos 3 %, monocitos 2 %, basófilos 2 %, plaquetas 135 000/ul, glucosa 91 mg/dL, creatinina 0.7 mg/dL. EMO: pH: 7.6, leucocitos ++, piocitos 12-15/campo, sangre++, nitritos +, bacterias ++, bacilos gram negativos 20/campo, proteínas +. Seleccione las conductas terapéuticas más adecuadas 1. Nitrofurantoína de liberación prolongada 50 mg/6 horas durante 1 semana. 2. Previa toma de urocultivo prescribir fosfomicina 3 gr vía oral dosis única. 3. Sulfato ferroso 30 mg/día por vía oral. 4. Hierro elemental 120 mg/día por vía oral. 5. Previa toma de urocultivo administrar cefoxitina 500 mg/ 12 horas vía oral. 6. Ácido fólico 400 ug/día por vía oral.",
