    "id": "html-748",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 34 años, primigesta, de 37 semanas de gestación, es transferida a la emergencia del hospital por presentar en la consulta externa cifras tensionales de 140 /90 con proteinuria negativa. Al interrogatorio, sintomatología vasomotora y percibe movimientos fetales. Sin antecedentes personales de importancia. Su madre tuvo preeclampsia en su primera gestación. Al examen físico: TA 140/95 mmHg, FC: 96 latidos/min. Abdomen gestante, altura de fondo uterino acorde con edad gestacional, feto único, vivo, cefálico izquierdo FCF 140 latidos /min. Reflejo patelar 2/5. Exámenes: Hematocrito 37 %, Plaquetas 150 000, ALT 29 AST 32 mUI, bilirrubina total 1 g/dl, Creatinina 0.5mg/dl, índice proteinuria/creatininuria 0.1. Se decide terminar el embarazo por parto céfalo vaginal. En el puerperio inmediato las cifras tensionales persisten en 140/90. ¿En cuánto tiempo después del parto define el diagnóstico diferencial de este trastorno hipertensivo?",
