    "stem": "Mujer de 75 años es llevada al servicio de emergencia por intenso dolor abdominal difuso de 28 horas de evolución, acompañado de diarreas acuosas vinosas. Antecedentes: fibrilación auricular en tratamiento irregular. Al examen físico presenta: FC: 95/min, FR: 21/min, TA: 100/60 mmHg, temperatura: 36°C. Corazón: ruidos cardiacos arrítmicos, no soplos. Abdomen: ruidos hidroaéreos disminuidos, suave, depresible, dolor intenso de forma difusa, sin defensa muscular ni signos de irritación peritoneal. Se decide realizar laparotomía exploratoria. ¿Cuál es el hallazgo más probable que se encuentre en la paciente?",
