  {
    "id": "html-750",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 48 años, sin antecedentes patológicos de interés, presenta desde hace 1 mes sensación de pesadez en su región malar derecha. Se acompaña de obstrucción nasal y rinorrea amarillenta, fétida por la fosa nasal derecha. Fue evaluada por un médico, quien consideró que se trataría de un cuadro de sinusitis bacteriana aguda, prescribió amoxicilina- ácido clavulánico durante 15 días, sin alcanzar mejoría clínica. Se practica una TC de senos paranasales que evidencia una ocupación del seno maxilar derecho, el resto de senos paranasales y las fosas nasales se encuentran libres. La ocupación del seno maxilar es heterogénea con calcificaciones en su interior. El seno no se encuentra dilatado ni presenta erosiones óseas. Dada la descripción de este cuadro, ¿Cuál sería su diagnóstico más probable?",
