    "id": "html-751",
    "subject": "Banco general de medicina",
    "stem": "Lactante de 4 meses acude a la consulta por tos y rinorrea abundantes desde hace 3 días. Su madre indica que desde esta mañana respira más rápido y se le hunden más las costillas. No ha tenido fiebre. Se le realiza lavado nasal efectivo en la consulta, expulsa gran cantidad de mucosidad. A los 5 minutos se reevalúa: mantiene tiraje subcostal e intercostal moderados, auscultación pulmonar con buena ventilación bilateral con abundantes sibilancias espiratorias en ambos campos pulmonares, frecuencia respiratoria de 67 rpm y SO2 de 94%. ¿Cuál es la conducta integral más adecuada para el manejo de este paciente?",
