    "stem": "Un niño de 8 años presenta desde hace 5 días dolor abdominal tipo cólico, con aumento progresivo de intensidad. Además, tiene frecuencia aumentada de sus deposiciones en 5 - 6 al día, de cantidad variable, tienen consistencia líquida, con presencia de moco, sangre y sin material purulento o de otro tipo. Últimamente presenta pujo al deponer. Su estado de conciencia y sus signos vitales son normales; sus mucosas están semihúmedas, sus conjuntivas son algo pálidas. Presenta dolor abdominal moderado a la palpación, especialmente en el marco colónico. ¿Cuál de los siguientes parásitos produce el cuadro clínico descrito?",
