    "stem": "Varón de 61 años acude a consulta externa para evaluación preoperatoria por hernia umbilical. Antecedente de cirrosis hepática en tratamiento clínico con espironolactona. Niega hábitos tabáquico y alcohólico actual. Encefalopatía estadio II. Examen físico: Tensión arterial 140/90 mmHg, frecuencia cardíaca 104 latidos por minuto, frecuencia respiratoria 24 por minuto, IMC 28 Kg/m2. Abdomen: onda ascítica. Hernia umbilical reducible. Telangiectasias periféricas. Laboratorio: Bilirrubina 2.5 mg/dL, Albumina 3 g/L, Tiempo de protrombina: 16 segundos. INR 1.2. ¿Cuál es el factor que predice menor riesgo quirúrgico en este paciente?",
