    "stem": "Hombre de 35 años es llevado a emergencias por presentar traumatismo en muslo derecho luego de una colisión vehicular. Es transportado con todas las medidas de inmovilización. Al examen físico: FC:98/min, FR:22/min, TA: 100/65mmHg, Glasgow 15. En muslo derecho hay intenso dolor y deformidad. La radiografía de extremidad inferior pone de manifiesto una fractura por avulsión del trocanter mayor. ¿Qué músculo podría seguir funcionando?",
