    "stem": "Un hombre de 25 años es llevado a Emergencias por personal paramédico, por presentar traumatismo penetrante de tórax hace 1 hora aproximadamente. Paciente se encuentra agitado, con dificultad respiratoria, y refiere dolor torácico. No se conocen antecedentes personales. Al examen físico FC: 110/min, FR: 30/min TA: 85 /55 mmHg temperatura: 36 °C, saturación de oxígeno: 80 % al aire ambiente. El tórax presenta herida penetrante de 1 cm a nivel de tercer espacio intercostal derecho en la línea medioclavicular, a la palpación presencia de enfisema subcutáneo perilesional, hemitórax derecho elevado, hiperresonancia a la percusión, con ausencia de murmullo vesicular; ruidos cardíacos rítmicos, taquicárdicos. El cuello presenta ingurgitación yugular. El hemograma muestra leucocitos de 12500/mm3 con 68 % de segmentados neutrófilos, hemoglobina de 12.5 g/dl. Tipificación sanguínea A Rh positivo. ¿Cuál es el procedimiento inmediato que se debe realizar en el paciente?",
