    "stem": "Según el esquema de control prenatal de las Guías de Práctica Clínica del MSP de Ecuador. ¿Cuáles son factores de riesgo para recomendar profilaxis antibiótica para el Streptococcus del grupo B (EGB) en el embarazo? 1. Antecedente de aborto séptico en el último año. 2. Ruptura prematura de membranas mayor a 18 horas. 3. Recién nacido previo con enfermedad invasiva por EGB. 4. Infección urinaria por EGB confirmada en el embarazo actual. 5. Aumento de la temperatura axilar mayor a 39 ºC.",
