    "stem": "Paciente masculino de 3 días de vida traído a emergencias por ictericia. Es hijo de madre de 27 años, embarazo controlado normoevolutivo, nacido a término por parto eutócico, apgar 9-10, alta a las 24 horas. Al examen físico frecuencia cardiaca 120 /minuto, frecuencia respiratoria 45/minuto, temperatura axilar 37 °C, saturación de oxígeno 95 %, cefalohematoma en región parieto-occipital derecha, ictericia generalizada, no otras anomalías. Exámenes: leucocitos 17 000/mm3, neutrófilos 50 %, linfocitos 55 %, hematocrito 50%, plaquetas 180 000/mm3, proteína C reactiva 0 mg/l, bilirrubina total 17 mg/dl, bilirrubina indirecta 16 mg/dl, grupo sanguíneo materno A+, grupo sanguíneo neonato O+. ¿Cuál es la causa más probable de su ictericia?",
