  {
    "id": "html-764",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 50 años acude a consulta médica por presentar dificultad para la deglución desde hace 2 años; la dificultad es igual para alimentos sólidos y líquidos, está acompañada de ardores retroesternales y regurgitación de saliva y alimentos, en especial en la noche cuando se recuesta. Además, refiere pérdida de peso. Sus antecedentes personales incluyen gastritis diagnosticada, sólo por síntomas y sin endoscopía, hace 1 mes toma omeprazol 40mg al día; a pesar de este tratamiento no ha sentido ninguna mejoría. Al examen físico FC: 60/min, FR: 18/min, TA: 120/75 mmHg, temperatura: 36.6 °C, no se evidencian hallazgos significativos. La endoscopia muestra dilatación del cuerpo esofágico y el cardias puntiforme que ofrece una moderada dificultad al paso del fibroscopio. No se observan cambios inflamatorios ni lesiones en la mucosa esofágica. El hemograma muestra leucocitos de 7500/mm3 con 68 % de segmentados neutrófilos. La química sanguínea muestra glucosa de 70 mg/dl y creatinina de 1.1 mg/dl. La paciente presenta un cuadro clínico compatible con:",
