    "stem": "Un escolar de 11 años, pesa 36 kg. Desde hace 24 horas presenta fiebre alta, odinofagia, malestar general y anorexia. T: 39.3 °C; FC: 96 x 1´; TA: 110/70 mmHg; Facies febril con mejillas enrojecidas y palidez perioral. Adenomegalias submaxilares dolorosas; hipertrofia y congestión amigdalina con exudado blanquecino, purulento. Algunas petequias diseminadas en el paladar blando. Determine el diagnóstico y tratamiento de primera elección:",
