    "stem": "Una adolescente cuya menarquia se presentó hace 2 años, consulta por palidez, cansancio y anorexia. Al examen se aprecia palidez palmar y un soplo sistólico en mesocardio grado 2/6. La biometría hemática revela un recuento eritrocitario disminuido y glóbulos rojos hipocrómicos y microcíticos. El recuento leucocitario y el plaquetario son normales, ¿Qué prueba de laboratorio solicitaría para establecer el origen de esta anemia?",
