    "id": "html-768",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 58 años, evaluada en urgencias por dolor abdominal. Refiere 18 horas de dolor abdominal que se ubica en cuadrante superior derecho desencadenado por la ingesta de grasa, ha tenido episodios similares previos en los últimos 3 años. Antecedentes de diabetes mellitus tipo II en tratamiento formal con metformina. Examen físico: Tensión arterial 140/90 mmHg, frecuencia cardíaca 110 latidos por minuto, frecuencia respiratoria 16 por minuto, T: 38 °C, IMC 31 Kg/m2. Abdomen: Murphy positivo. Ruidos hidroaéreos disminuidos. Laboratorio: Hemoglobina glicosilada: 5.9 %. Ecografía: colecistitis aguda sin dilatación de la vía biliar. ¿Cuál es el riesgo quirúrgico de ASA (American Society of Anesthesiologists) para esta paciente?",
