  {
    "id": "html-770",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 45 años consulta por presentar dolor abdominal en hipogastrio de cuatro meses de evolución, es persistente a lo largo del ciclo y no mejora con la menstruación. Sin antecedentes personales de importancia. Antecedentes gíneco obstétricos: menarquia a los 11 años, ciclos menstruales cada 28 días por 5 días, FUM: hace 15 días, dismenorrea primaria, planificación familiar preservativo. G1 P1 hace 4 años. Al examen físico: TA: 110/67 mmHg , FC: 68/min, FR: 18/min, T: 37 °C. El abdomen es doloroso a la palpación en hipogastrio y fosas ilíacas, Blumberg negativo. Región genital: flujo vaginal normal. Al tacto vaginal: útero en retroversoflexión, fijo, anexo izquierdo doloroso y aumentado de tamaño, con dificultad para su delimitación por dolor. Anexo derecho no palpable. La ecografía reporta un quiste de ovario izquierdo de 7 cm de diámetro con contenido finamente particulado (imagen de vidrio esmerilado). ¿Cuál es el diagnóstico más probable de la paciente?",
