    "stem": "Paciente masculino de 2 años, sin antecedentes de importancia, acude a emergencias por presentar fiebre de 3 días de evolución, rinorrea, tos. Desde hace 12 horas presenta somnolencia, irritabilidad, vómitos en proyectil. Al examen tiene 39 °C, mal estado general, taquicárdico, taquipnea, rigidez nucal, signos de Kernig y Brudzinski positivos. Biometría hemática: leucocitos 4000/mm3, neutrófilos 50 %, linfocitos 40 %, monocitos 10%, hemoglobina 12 gr/dl, hematocrito 36%, plaquetas 60.000/mm3, procalcitonina 5 ug/ml. Líquido cefalorraquídeo: leucocitos 1000/mm3, neutrófilos 70 %, mononucleares 30 %, proteínas 200 mg/dl, glucosa 35 mg/dl, glucemia 100 mg/dl. ¿Cuál es la antibioticoterapia inicial para este paciente?",
