    "stem": "Lactante de 1 año con letargia, náusea, disfonía, aversión a las tomas, crecimiento retardado, estridor, episodios de otitis media, sinusitis ocasional. Al examen no se observan lesiones bucales ni orofaríngeas. No refiere dolor retroesternal, se ha suspendido medicación oral desde hace 6 meses, no refiere alergias cutáneas o alimentarias. ¿Cuál es el diagnóstico?",
