  {
    "id": "html-773",
    "subject": "Banco general de medicina",
    "stem": "Hombre de 55 años, acude a consulta externa por urgencia miccional y disminución en el calibre del flujo de orina, 4 meses de evolución. Antecedentes: prostatitis aguda a los 40 años. En el examen físico: TA: 110/70 mmHg, FC: 68 LPM, FR: 16 RPM. Tacto rectal se palpa próstata sin anomalías. Resto de la exploración normal. Se revisa complementarios de 6 meses atrás: PSA total 15 ng/ml, ecografía pélvica con próstata peso 70 gr. Complementarios actuales: Densidad de PSA aumentada, Velocidad de PSA 0.3 ng/ml/año, ecografía transrectal con próstata 75 gr. ¿Cuál de las siguientes opciones justifica la indicación de biopsia prostática?",
