  {
    "id": "html-774",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 16 años acude a consulta, en donde refiere que realiza ayuno voluntario e intermitente desde hace 8 meses. Aclara no haber tomado laxantes, ni estimulado al vómito. Adicionalmente, confiesa temor permanente a subir de peso y considera que debería ser inferior al que presenta en el momento de la consulta. Antecedentes personales: no ha presentado trastorno mental. Al examen físico: IMC 19 kg/m2. ¿Cuál es el diagnóstico más probable?",
