  {
    "id": "html-775",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 32 años junto a su esposo, acude a su consulta consternada por presentar 3 abortos espontáneos, cada uno antes de llegar a las 12 semanas de gestación. La paciente refiere que hace 5 meses ha intentado concebir sin éxito, en ese tiempo nota que no tolera las temperaturas bajas, presenta un estado de ánimo depresivo y refiere fatigada todo el tiempo. El mes pasado el ginecólogo le diagnostica hipotiroidismo subclínico. En su familia su madre y abuela materna padecen de enfermedades autoinmunes. Al examen físico encuentra una temperatura de 36.8 °C, TA: 100/60 mmHg, FR: 16/min, FC: 79/min, Sat O2: 95%, peso: 48 kilos, talla: 1.53 cm. La paciente se encuentra consciente orientada, sin alteraciones al examen físico. Los exámenes de laboratorio presentan: Hemograma: leucocitos 9.300 /mm cúbico, hemoglobina: 16 g/dL. Glucosa: 86.2 mg/dL, creatinina 0.74 mg/dL, colesterol total 172.7 g/dL. ¿Cómo esperaría encontrar el perfil tiroideo de esta paciente?",
