    "id": "html-776",
    "subject": "Banco general de medicina",
    "stem": "Un paciente de 14 años es llevado a la emergencia por sus padres, quienes lo encontraron inconsciente en el piso de su dormitorio hace menos de una hora. Al momento del interrogatorio el paciente se encuentra consciente pero no recuerda su nombre ni reconoce a sus padres, pero recuerda vagamente eventos del día anterior. Al examen físico no se encuentran hallazgos de importancia. Cómo único antecedente importante los padres refieren que el paciente tuvo una riña con su pareja días antes, lo que le generó mucha ansiedad. ¿Qué trastorno parecería presentar este paciente?",
