    "id": "html-778",
    "subject": "Banco general de medicina",
    "stem": "Mientras usted realiza su rotación de Neumología, se le encarga el cuidado de un paciente de 72 años que fue internado por presentar: disnea, dolor de tipo pleurítico, fiebre y baja de peso. El examen físico realizado por el residente muestra una FR de 24/min, disminución de entrada de aire en el lóbulo pulmonar inferior izquierdo acompañado de un sonido mate a la percusión. Se solicita una placa PA y lateral de tórax que da muestra de un derrame pleural, se realiza una toracocentesis obteniéndose un fluido pleural de tipo hemorrágico. El residente antes de terminar su turno ordena los siguientes análisis. LDH sérico 110 U/L (N: 45-90), proteínas totales 8 g/dl (6.0-7.8 g/dL), LDH fluido pleural 230 U/L, proteínas en fluido pleural 14 g/dL. Elija el diagnóstico más probable de este caso:",
