  {
    "id": "html-779",
    "subject": "Banco general de medicina",
    "stem": "Una paciente de 20 años acude a la consulta por presentar una masa en su seno izquierdo. La paciente descubrió dicha masa al bañarse y ha estado presente por seis meses. La masa no es dolorosa, no le genera molestias y no hay antecedente de trauma. Su menarquia ocurrió a los 13 años y sus ciclos menstruales son regulares. Nunca ha estado embarazada y toma contraceptivos orales. Su historia familiar es positiva por cáncer de mama en una tía materna a la edad de 55 años. Al examen físico, sus signos vitales son normales. El examen mamario muestra mamas simétricas. En la unión de los cuadrantes externos de la mama izquierda se palpa una masa firme, móvil, de aproximadamente 3 cm. de diámetro. No se palpa nódulos axilares. Un ultrasonido mamario revela una masa ovoide, sólida, horizontal, hipoecogénica, de bordes regulares, de mediana dureza, con mínima vascularización. ¿Cuál es el diagnóstico más probable?",
