    "id": "html-781",
    "subject": "Banco general de medicina",
    "stem": "Paciente de 60 años y 60 kg de peso, hipertenso en tratamiento con losartan 50/día. Sufre caída casual con esguince de tobillo derecho grado I, está con vendaje desde hace 10 días y con tratamiento de: ibuprofeno, paracetamol alternados cada 8 horas y omeprazol 20 mg/día. Acude a urgencias por disnea súbita y dolor torácico derecho en punta de dedo, no irradiado, sin cortejo vegetativo. EF: Consciente, orientado. Glasgow 15/15. TA: 118/77 FC: 116 lpm. SatO2: 93 % aire ambiente. T: 36.2. AC: RCR no soplos. AP: MV conservado, sin ruidos sobreañadidos. MMII: Homans dudoso en pierna derecha. Resto sin alteraciones significativas. ECG: taquicardia sinusal a 112 lpm sin alteraciones de la repolarización. Plaquetas 78 000, Hb 14 g/dL Hto: 45 %, Creatinina 1 mg/dL, coagulación normal. Dímero D: 610 ng /ml (N: <500 ng/ml). Gaso arterial pH: 7,49 PCO2: 30 mm Hg, PaO2: 62 mm Hg, HCO3: 14 meq/lt, SatO2: 93%. Rx tórax: normal. ¿Cuál es el tratamiento inicial de elección para este paciente?",
