    "stem": "Varón de 18 años, evaluado en urgencias por dolor abdominal. Niega antecedentes médicos de importancia. Refiere 18 horas de dolor abdominal que inicio en región periumbilical y se localizó en cuadrante inferior derecho. Examen físico: Tensión arterial 120/80 mmHg, frecuencia cardíaca 110 latidos por minuto, frecuencia respiratoria 18 por minuto, T 38,4 ° C. Abdomen: dolor con defensa en cuadrante inferior derecho. Ruidos hidroaéreos disminuidos. Se decide realizar evaluación quirúrgica. ¿Cuál es el riesgo quirúrgico de ASA (American Society of Anesthesiologists) para este paciente?",
