    "id": "html-787",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 39 años acude a la consulta externa por debilidad muscular progresiva desde hace aproximadamente 4 meses y en las últimas 2 semanas se acompaña de ptosis palpebral, sin causa aparente. La debilidad se intensifica con la actividad en las horas finales del día y mejora tras el reposo. No presenta antecedentes de importancia. A la exploración física se objetiva: TA: 118/75 mm Hg, FC: 78 lpm, T:36 °C, ptosis palpebral bilateral y disminución de la fuerza muscular en los miembros superiores, resto de la exploración dentro de la normalidad. Diagnóstico de miastenia grave. ¿Qué órgano presenta anomalías con mayor frecuencia en esta patología?",
