    "id": "html-788",
    "subject": "Banco general de medicina",
    "stem": "Para garantizar la seguridad de la desfibrilación convencional o automática, el operador del desfibrilador no debe utilizar radios de comunicación, porque impide el funcionamiento del DEA. Señale en qué paso se realiza esta interferencia:",
