  {
    "id": "html-789",
    "subject": "Banco general de medicina",
    "stem": "Mujer primigesta de 33 años, con embarazo de 38 semanas y 5 controles prenatales normales. Se encuentra en trabajo de parto fase expulsiva. Al minuto el neonato presenta: frecuencia cardiaca menor a 100/minuto, llanto débil, leve flexión de extremidades, sin irritabilidad refleja, piel rosada en tronco, extremidades cianóticas. Usted realizó reanimación adecuada, tras lo cual a los 5 minutos el recién nacido tiene: frecuencia cardiaca mayor a 100/minuto, llanto vigoroso, leve flexión de extremidades, irritabilidad refleja con leve movimiento, su tronco continúa rosado y las extremidades cianóticas. ¿Cómo califica la puntuación de Apgar al 1 minuto y a los 5 minutos, respectivamente?",
