  {
    "id": "html-792",
    "subject": "Banco general de medicina",
    "stem": "Niña de 13 años presenta tos desde hace 2 semanas, luego de asistir a un campamento de verano. Ha recibido distintos antitusígenos y antihistamínicos en varios centros de salud, sin obtener un diagnóstico concreto. Ha mejorado poco. Tiene fiebre de 37.8 °C. desde hace 48 horas y presenta una mucosidad espesa que le causa tos paroxística durante el día y la noche. Frecuentemente la tos termina con un estridor en inspiración, seguido de vómito, que hace enrojecer su rostro y genera un estado de fatiga extrema. En los informes de urgencias, la auscultación es siempre normal. Su hermana de 6 años lleva también dos semanas con tos. Como antecedentes presenta una dermatitis atópica moderada. Sus padres no saben si recibió todas las vacunas. ¿Cuál es el diagnóstico inicial más probable?",
