    "stem": "Una niña de 5 años presenta dolor intenso de oído derecho de 24 horas de evolución. La niña se encuentra febril. Al examen otoscópico neumático del oído derecho se evidencia un eritema intenso de la membrana timpánica con abombamiento moderado de la misma; además se evidencia líquido y niveles hidro-aéreos detrás de la membrana timpánica. El diagnóstico correcto de la condición de la paciente es:",
