    "stem": "Hombre de 38 años, sin antecedentes de interés. Acude a la emergencia hospitalaria por presentar desde hace 4 horas dolor periumbilical difuso y sensación distérmica sin otros síntomas acompañantes. A la exploración McBurney positivo. Los exámenes de laboratorio no muestran alteraciones. En la ecografía abdominal se objetiva apéndice no comprimible de 7 mm de diámetro. ¿Qué signos y/o síntomas son característicos del cuadro descrito?",
