    "stem": "Varón de 15 años evaluado en urgencias por politraumatismo debido a accidente de tránsito. Niega antecedentes médicos de importancia. Accidente se da como acompañante con uso de cinturón de seguridad. Examen físico: Tensión arterial 90/60 mmHg, ortostatismo positivo, frecuencia cardíaca 145 latidos por minuto, se estima una pérdida de sangre mayor del 40 %. frecuencia respiratoria 35 por minuto, SAT O2 aire ambiente 88 %. Paciente en coma. Abdomen: suave, depresible, doloroso en marco colónico. Ruidos hidroaéreos disminuidos. Laboratorio: Hemoglobina 9 g/dL. Hematocrito 27 %. Leucocitos 5.5 k/uL. Plaquetas: 250 k/UL. Tiempo de protrombina 12 INR 1. ¿Qué clase de shock hemorrágico tiene este paciente?",
