  {
    "id": "html-858",
    "subject": "Banco general de medicina",
    "stem": "Gestante de 30 años, con 34 semanas de embarazo, fumadora habitual desde los 24 años de 10 unidades a la semana, hace 4 meses ha disminuido a 3 unidades a la semana, sin otros antecedentes de interés. Refiere que hace 4 días realizó vuelo transatlántico de 10 horas, desde entonces nota edema y dolor en la región posterior de la pierna derecha que ha ido en aumento y empeora con la deambulación. Desde hace 1 día presenta además disnea de moderada intensidad que aumenta con el esfuerzo físico. En el control prenatal hace 1 semana le indicaron que estaba todo normal y recomendaron abandonar el tabaco. No antecedente traumático, no fiebre, no dolor torácico ni tos. Examen físico: Consciente, orientada. Glasgow 15/15. TA: 118/74 FC: 122 lpm. SatO2: 93% aire ambiente. T: 36.2. AC: RCR, soplo pansistólico grado II/VI. AP: MV conservado, sin ruidos sobreañadidos. Pierna derecha: Edema con fóvea +, aumento del perímetro respecto a contralateral, tibial anterior disminuido, Homans dudoso. No eritema ni aumento de temperatura local. Resto sin alteraciones significativas. Hemograma, bioquímica y coagulación normales. PCR 2. Dímero D: 572 ng/ml (N: <500 ng/ml). Ecocardiografía transtorácica: derrame pericárdico benigno y signo de McConnell. Señale lo correcto respecto a la patología de la paciente:",
    "options": [
