      "El electrocardiograma tiene alta sensibilidad, es típico la taquicardia sinusal con onda S en III, T invertida en I, onda Q en III.",
      "La presencia de derrame pericárdico benigno al estar embarazada es un criterio de mal pronóstico que precisa ingreso hospitalario inmediato.",
      "El ecocardiograma es un método diagnóstico de primera elección antes del enzimoinmunoanálisis de adsorción con dímero D."
    ],
