    "id": "html-861",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 28 años cursando su primer embarazo de 39 semanas acudió al servicio de emergencia porque refiere presencia de contracciones uterinas. Comunica que las contracciones iniciaron hace 8 horas pero que cada vez son más frecuentes e intensas, los movimientos fetales se encuentran presentes. No ha presentado sangrado ni salida de líquido por vía vaginal. Sus antecedentes obstétricos incluyen primera gesta, con controles prenatales mensuales y ecografías dentro de la normalidad. Al examen físico FC: 84/min, FR: 21/min, temperatura 36 °C, TA: 115/75 mmHg. FCF: 155/min. Abdomen gestante con fondo uterino a término, feto único móvil, en presentación cefálica. Al tacto vaginal cuello uterino posterior dilatado 4 cm y con 50 % de borramiento, membranas íntegras, se palpa cabeza fetal en segundo plano de Hodge. En la monitorización electrónica fetal se observa desaceleración de la frecuencia cardíaca fetal cuyo inicio, nadir y recuperación coinciden con el comienzo, el pico y el final de la contracción uterina. ¿Cuál es la causa más probable de la desaceleración cardíaca fetal encontrada?",
