    "stem": "Mujer de 25 años, contrajo matrimonio hace un año, pero no ha logrado quedarse embarazada. Sus ciclos menstruales son irregulares, no toma ningún fármaco. Desde hace 4 meses hay amenorrea y presenta desde hace dos meses galactorrea y cefalea fronto temporal bilateral opresiva, progresiva en intensidad. La beta gonadotropina coriónica fue negativa, los niveles de prolactina son 85 ng/ml (normal hasta 20 ng/ml), FSH 3.6 IU/L (rango 4.5-21IU/L), LH 4.8 UI/L (5-25 UI/L). Los niveles de TSH, ACTH y GH fueron normales. La IRM de encéfalo simple y con contraste reveló una masa sólida, homogénea de 22 mm de diámetro en la silla turca, hipointensa en las secuencias T1 y T2, sin captación de contraste. La lesión tiene extensión supraselar y hacia el seno cavernoso. Se solicita una campimetría visual. ¿Cuál es el tipo de déficit en la campimetría que debe tener esta paciente?",
