    "id": "html-865",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 66 años fue recientemente diagnosticada de mieloma múltiple. Consulta al médico a causa de disnea que se ha incrementado progresivamente, lo que le impide subir gradas o realizar las tareas de la casa. Al examen se aprecia edema con fóvea, bilateralmente en sus miembros inferiores, hay matidez de concavidad superior en el abdomen y distensión yugular. No se palpa el ápice cardíaco ni se ausculta frote. Hay crepitantes pulmonares bilaterales. La TA: 130/85 mm Hg. FC: 86 lpm, FR: 20 x min. Un ECG muestra disminución difusa del voltaje. La Rx de tórax es normal y un ECO cardiograma revela ventrículos pequeños con incremento del grosor de sus paredes y atrios dilatados con engrosamiento del septo interatrial. El miocardio tiene una textura granular y se observa acumulación mínima de fluido en el espacio pericárdico. ¿Cuál es el diagnóstico más probable?",
