    "subject": "Banco general de medicina",
    "stem": "Una mujer de 47 años es llevada a Emergencias por personal paramédico, a causa de traumatismo penetrante de tórax hace 1 hora aproximadamente. No se conocen antecedentes personales patológicos. Al examen físico FC:120/min, FR: 25/min TA: 95 /55 mmHg temperatura: 36 °C, saturación de oxígeno: 88 % al aire ambiente. En región cervical ingurgitación yugular. El tórax presencia de herida de 2 cm localizada a nivel de 4 espacio intercostal 3 cm medial al pezón, campos pulmonares con presencia de murmullo vesicular normal, ruidos cardíacos hipofonéticos. ¿Cuál sería el paso inicial recomendado en esta paciente?",
