    "id": "html-869",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 40 años, acude a emergencia por debilidad en los miembros inferiores que comenzó hace 10 días, hace 3 días nota también debilidad en las manos. Desde el inicio de la debilidad hace 10 días, hay sensación de hormigueo en los dedos de los pies. No tiene ninguna enfermedad previa, excepto que hace dos semanas tuvo un resfriado común. La TA en emergencia es de 110/70 mm Hg, saturación de O2 de 92% (aire ambiente), Fc de 76 por minuto. Glasgow 15/15. El balance muscular en los 4 miembros es de 4/5 a nivel proximal y de 3+/5 a nivel distal. Hay arreflexia osteotendinosa en los 4 miembros y una hipoestesia en bota corta para la sensibilidad táctil y al pinchazo. Usted decide realizar una punción lumbar. ¿Cuál es el resultado que se debe encontrar en el líquido céfalo raquídeo en esta paciente?",
