  {
    "id": "html-870",
    "subject": "Banco general de medicina",
    "stem": "Un hombre de 35 años, acude a consulta de urología por presentar lesiones ulcerosas muy dolorosas en el pene; refiere que hace 7 días mantuvo relaciones sexuales sin anticonceptivo de barrera con una trabajadora sexual, hace 4 días presento “unos granos” en el pene no dolorosos que posteriormente drenaron pus y se tornaron dolorosos. No ha presentado disuria. Sus antecedentes personales incluyen: infección de vías urinarias hace 1 año que se resolvió con tratamiento que no especifica. Al examen físico FC: 80/min, FR: 20/min, TA: 120/75 mmHg, temperatura: 37.7 °C. En el lado derecho del surco coronal del pene se observa dos úlceras muy dolorosas y no induradas, con bordes irregulares; las úlceras contienen secreción amarillenta, al realizar un raspado se presenta sangrado. Se palpan adenopatías inguinales derechas dolorosas. El hemograma muestra leucocitos de 12000/mm3 con 77 % de segmentados neutrófilos. La química sanguínea muestra glucosa de 110 mg/dl y creatinina de 1.1 mg/dl. ¿Cuál es el agente etiológico responsable de este cuadro clínico?",
    "options": [
