    "id": "html-872",
    "subject": "Banco general de medicina",
    "stem": "Paciente de 32 años, con embarazo de 38 semanas, acude a emergencia del hospital por presentar cefalea intensa. Familiar refiere que la paciente hace 1 hora presentó convulsiones generalizadas. A la exploración física: TA: 150/110 mmHg, FR: 18 rpm, T: 36.5 °C, FC: 80 lpm. Exámenes complementarios: determinación de proteínas en orina con tira reactiva y con resultado negativo, plaquetas 250 000/uL, TGO 28 UI/L, TGP 32 UI/L, creatinina sérica 0.7 mg/dL, LDH 300 UI/L, en este caso. ¿Qué dosis de sulfato de magnesio intravenoso se utiliza como impregnación en profilaxis de convulsiones?",
