  {
    "id": "html-873",
    "subject": "Banco general de medicina",
    "stem": "Un lactante mayor de 18 meses de edad acude al subcentro de salud por presentar desde hace 24 horas diarreas líquidas, abundantes, mal oliente, sin moco ni sangre, en número de 10. Al examen físico presenta astenia; sin embargo, se pone irritable al manejo, tiene los ojos algo hundidos, globos oculares blandos y el llanto sin lágrimas. Su lengua y mucosas orales están secas. Presenta signo de pliegue únicamente en abdomen. T: 38,7 °C, FC: 116 x 1´, FR: 40 x 1´. Llenado capilar rápido. No ha vomitado y toma un poco de seno materno. Su peso actual es de 9.2 kg. El último registro de su peso es de 9.8 kg. La madre del lactante refiere que este ha orinado poco y su orina es de un color amarillo intenso. Determinar el grado de deshidratación y la mejor opción para su tratamiento:",
