    "stem": "Recién nacido con las siguientes características vitales al minuto de nacimiento: Frecuencia cardiaca 80 x minuto; llanto débil; moderada flexión de extremidades; irritabilidad refleja con llanto y retirada al limpiarle las secreciones de la boca; cuerpo rosado y extremidades azuladas. ¿Cuál es la calificación de APGAR para este caso?",
