  {
    "id": "html-875",
    "subject": "Banco general de medicina",
    "stem": "Un niño de 4 años y 16.6 kg de peso tiene disentería grave. Se encuentra bien hidratado pues recibió hidratación oral. T: 39.5°C. Tenesmo intenso y cólicos abdominales. Las deposiciones son muco sanguinolentas. ¿Cuál es la mejor decisión terapéutica?",
