    "stem": "Una mujer de 76 años acude a consulta médica por cuadro de un mes de evolución de presencia de sangre en la orina, no presenta dolor. No refiere molestias urinarias ni genitales. Además, ha presentado pérdida de peso en los últimos 3 meses. Sus antecedentes personales incluyen hipertensión arterial desde hace 15 años en tratamiento con enalapril 10mg diarios, fumadora de 20 unidades de cigarrillo al día desde los 30 años. Al examen físico FC: 88/min, FR: 19/min, TA: 135/85 mmHg, temperatura: 36.7 °C. El examen físico regional es completamente normal. El hemograma muestra leucocitos 7000/mm3 con 58 % de segmentados neutrófilos, hemoglobina 11.5 g/dl. El examen de orina muestra campo lleno de hematíes, ausencia de bacterias y piocitos. Considerando su sospecha diagnóstica. ¿Cuál de las siguientes opciones confirmará mejor el diagnóstico?",
