    "stem": "Un varón soltero, de 26 años con antecedente de una relación sexual sin protección hace 15 días, acude a su consulta por una lesión genital. Inició hace unos 6 días como una mácula en el prepucio que progresó a pápula, con posterior salida de material purulento y dolor. Al examen físico se encuentra una úlcera redondeada, algo deprimida, de aproximadamente un centímetro de diámetro, de bordes difusos y suaves, irregulares y piel eritematosa en su contorno. Se evidencia un exudado purulento, gris, abundante, en el fondo de la úlcera. Además presenta un ganglio inguinal derecho palpable y doloroso, de 1.5 centímetros de diámetro. ¿Para cuál de los siguientes microorganismos direccionaría la terapéutica?",
