    "stem": "Señale la enfermedad aguda autolimitada de la lactancia y la primera infancia que se caracteriza por la aparición brusca de fiebre alta, que suele resolverse después de 72 horas (crisis), pero puede disminuir de forma gradual durante un día (lisis) coincidiendo con la aparición en el tronco de un exantema morbiliforme de color rosa o ligeramente enrojecido y no pruriginoso, de 2-3 mm. El exantema suele durar 1-3 días, pero a menudo se describe como evanescente y puede ser visible sólo durante horas, extendiéndose desde el tronco hasta la cara y las extremidades. Los signos asociados pueden consistir en congestión leve de la faringe, la conjuntiva palpebral o el tímpano, y en un aumento de tamaño de los ganglios suboccipitales.",
