    "id": "html-905",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 58 años, 50 kg de peso, residente en Manta y sin antecedentes de interés. Sufre traumatismo craneal grave (TCE) con Glasgow en 8/15. TA 80/50 mm Hg. Glicemia: 280 mg/dl, Hb: 8 g/dL, Sat O2: 90 %. Le administran oxígeno, cloruro de sodio al 0.9 % hasta normalizar la TA. Presenta convulsiones que se manejan con fenitoína. Los signos de hipertensión intracraneal se trataron con manitol 100 gr iniciales en 20 minutos. Seleccione las respuestas correctas en cuanto al manejo inicial en este caso y objetivos terapéuticos en el TCE grave: 1. En el manejo de la hipotensión el ringer lactato y el cloruro de sodio al 0.9 % son recomendados por igual. 2. La presión arterial sistólica mayor a 100 mm de Hg garantiza una presión de perfusión cerebral adecuada. 3. La glicemia que presenta el paciente es el objetivo a alcanzar por el riesgo a desarrollar hipoglucemia. 4. Se debió haber realizado hiperventilación hasta lograr una PaCO2 menor a 35 mm de Hg. 5. El manejo de los signos de hipertensión intracraneal utilizando manitol fue adecuado. 6. El valor de hemoglobina que presenta el paciente está dentro del objetivo del tratamiento de la lesión cerebral.",
    "options": [
