    "stem": "Paciente femenina de 25 días de vida, atendida por presentar ictericia desde el nacimiento. En sus antecedentes perinatales se destacan prematurez y peso bajo para edad gestacional (36 semanas - 1800 gramos). Al examen signos vitales normales. Peso, talla y perímetro cefálico bajos para edad gestacional, rash maculopapular generalizado, hepatoesplenomegalia, ictericia. La tomografía de cráneo contrastada reveló calcificaciones corticales, fondo de ojo con coriorretinitis izquierda, audiometría y ecocardiograma normales. Biometría con leucocitos 13 000/mm3, fórmula normal, hematocrito 55 %, plaquetas 130 000/mm3, TGO 60 (elevada), TGP 75 UI/l (elevada). ¿Cuál es la infección congénita más probable en esta paciente?",
