    "stem": "Un paciente varón de 34 años acude a la consulta externa, con un cuadro de 6 meses de evolución que se presenta cada 15 a 20 días, de dolor abdominal difuso, de intensidad EVA 4-5/10, distensión abdominal, flatulencia y diarrea acuosa maloliente, sin moco ni sangre que alternan con deposiciones normales. No refiere pérdida de peso, ni alza térmica. Niega vómito o sangrado digestivo macroscópico. Sus signos vitales son normales y el examen físico, incluido el abdomen, es normal. Acude con resultados de laboratorio: leucocitos 5 800 x 109/L Neut 56 % Hemoglobina 15.4 mg /dL. ¿Qué examen le ayudaría a confirmar su principal sospecha diagnóstica?",
