    "stem": "Mujer de 65 años acude a consulta externa por seguimiento de diabetes. Refiere que hace 1 mes inició tratamiento con antidiabéticos orales y en las últimas 3 semanas ha presentado 3 episodios documentados de hipoglucemia. Niega antecedes médicos adicionales. Al examen físico presenta: Índice de masa corporal: 27 Kg/m2, tensión arterial: 120/80 mmHg, frecuencia cardíaca: 80 latidos por minuto, frecuencia respiratoria: 14 por minuto. Sat O2 aire ambiente: 94 %. No presenta focalidad infecciosa o neurológica. Laboratorio: glucosa 140 mg/dL, hemoglobina glicosilada 7.5 %. ¿Qué familia de fármacos ocasiona con mayor frecuencia el efecto adverso que presenta la paciente?",
