    "stem": "Un recién nacido, producto de la primera gesta de una madre de 23 años. Tuvo una labor de parto de 12 horas, ruptura de membranas intraparto, líquido amniótico claro y grumoso. Nació de parto normal en un servicio hospitalario. Al nacer presentó un Peso de: 2.9 kg; Talla: 49 cm; PC: 34.5 cm; APGAR: 7/9; A las 24 horas de edad presenta ictericia en cara y tronco. La bilirrubina indirecta es de 7 mg/dl. La bilirrubina directa es de 0.9 mg/dl. Se encuentra activo, tiene buena reactividad al manejo. Toma seno materno exclusivo, con succión adecuada. Presentó regurgitación por dos ocasiones. El grupo sanguíneo de su madre es A+; el RN es 0+ y Coombs directo es negativo. Seleccione el diagnóstico, así como la decisión terapéutica correcta para su ictericia:",
