    "subject": "Banco general de medicina",
    "stem": "Una mujer de 38 años acude a consulta por retraso menstrual de 5 días, se realiza prueba de embarazo en orina y es negativa. Sin antecedentes personales de importancia. Antecedentes gineco obstétricos: ciclos menstruales regulares cada 28 días x 4 días, flujo normal, dismenorrea leve. Fecha de la última menstruación 33 días antes de la consulta. G2 C2. Examen físico de la región genital: Tacto vaginal: útero en anteversión de tamaño normal para la edad y la paridad de la paciente, bordes regulares no doloroso a la movilización, en el anexo derecho se palpa masa de aproximadamente 5 cm, móvil, de bordes regulares, de consistencia blanda, no dolorosa. Anexo izquierdo normal. Eco pélvico transvaginal: útero de características ecográficas normales, endometrio de 13mm. Ovario derecho: masa redondeada anecoica de contenido líquido simple, bien definida de bordes regulares, paredes delgadas, avascular de 4. 5 cm de diámetro con reforzamiento posterior y otra de las mismas características de 3.1cm de diámetro. Anexo izquierdo normal. ¿Cuál de las siguientes opciones de manejo es la más adecuada?",
