    "stem": "Un hombre de 45 años consulta por cefalea, rinorrea, otalgia, fiebre, artralgias y anorexia. Este cuadro ha ocurrido desde hace más de tres meses. Hace dos semanas fue evaluado por un médico quien solicitó una radiografía de senos paranasales en la que se apreció una sinusitis maxilar bilateral. Le prescribió antibiótico, pero en lugar de mejorar su cuadro, se añadió: tos, dolor torácico y hemoptisis. El examen físico revela los siguientes hallazgos: deformidad nasal en silla de montar, ulceración en la mucosa nasal. Los exámenes reportan: BUN: 35 mg/dl, creatinina sérica: 2 mg/dl, EMO: 10-12 eritrocitos por campo de alto poder. La RX de tórax muestra infiltrados cavitarios bilaterales. El examen de expectoración: BAAR: negativo, ausencia de hongos o células malignas. ¿Cuál sería el diagnóstico más probable?",
