    "stem": "Mujer de 35 años secundigesta de 38 semanas, acude a emergencias según refiere por contracciones uterinas, que iniciaron hace 6 horas, pero que cada vez son más intensas y frecuentes, además nota los movimientos fetales. No tiene sangrado ni salida de líquido por la vagina. Antecedentes obstétricos: primera gesta, con controles prenatales y ecografías normales. Al examen físico presenta: FC: 74/min, FR: 21/min, temperatura 36 °C, TA: 115/80 mmHg. Abdomen: gestante con fondo uterino a término, en presentación cefálica y FCF (frecuencia cardíaca fetal): 155/min. Al tacto vaginal cuello uterino posterior dilatado 2 cm y con 30% de borramiento, membranas íntegras y se palpa la cabeza fetal en segundo plano de Hodge. En la monitorización electrónica fetal se observa una caída aguda de la FCF con una pendiente rápida descendente y una recuperación variable, como \"v\", este hallazgo tiene una relación variable con las contracciones. ¿Cuál es la causa más probable de la desaceleración cardíaca fetal encontrada?",
