    "stem": "Mujer de 26 años, con 4 abortos de repetición, trombosis venosa profunda de pierna derecha hace 3 años. Es hospitalizada, a la exploración: soplo sistólico pulmonar 3/4. Plaquetas 200 000, anticoagulante lúpico y anticuerpos anticardiolipina positivos a título alto. Eco transtorácico y transesofágico: masa móvil de 4.3 x 1.2 cm en el tracto de salida del ventrículo derecho (VD) en forma de racimo que prolapsa en sístole hacia la arteria pulmonar. ¿Cuál es la alternativa de anticoagulación de primera elección para este paciente?",
