    "subject": "Banco general de medicina",
    "stem": "Paciente femenina de 18 años, estudiante universitaria, reside en Quito. Lateralidad diestra. Hace 3 días presentó astenia, hiporexia, malestar general, alza térmica no cuantificada y 4 deposiciones diarreicas sin moco ni sangre. Hace 24 horas por primera vez presentó cefalea occipital, opresiva, con náusea y vómito en dos ocasiones. En emergencia, la TA es de 120/70 mmHg, Fc 84 LPM, temperatura bucal 38.3°C, saturación O2 (aire ambiente) 93%. La paciente esta somnolienta, orientada en persona, espacio y tiempo. El lenguaje y el fondo de ojo son normales. No hay compromiso de pares craneales, ni déficit motor. Hay rigidez de nuca y signo de Kernig. La biometría revela leucocitos 11.210 mm3; linfocitos 60%, neutrófilos 32%; Proteína C reactiva de 5.9 mg/L, glucosa sérica de 83 mg/dl. El líquido céfalo raquídeo muestra un aspecto turbio, 385 leucocitos/mm3; 70% linfocitos, proteínas de 62 mg /dL y glucosa de 50 mg/dL. ¿Cuál es el diagnóstico más probable en esta paciente?",
