    "id": "html-963",
    "subject": "Banco general de medicina",
    "stem": "Hombre de 15 años, acude a consulta externa por odinofagia y fiebre, de 24 horas de evolución, no náuseas ni vómitos. No alteraciones del ritmo intestinal ni síntomas urinarios. Antecedentes: faringoamigdalitis estreptocócica aguda reciente. A la exploración física presenta: FC: 94 lpm. T: 38.5 ºC, FR: 20 rpm. Consciente y orientado en las tres esferas. Piel: exantema eritematoso. Exploración orofaríngea: lengua roja con descamación de las papilas, amígdalas eritematosas y faringe cubierta con una película membranosa amarilla. Linfadenopatía a nivel del cuello. Cardiopulmonar: normal. Resto de la exploración normal. Dentro de las complicaciones que puede presentar el paciente. ¿Cuál es el diagnóstico probable según el cuadro actual?",
