    "subject": "Banco general de medicina",
    "stem": "Un niño de 5 años es llevado al servicio de emergencias por cuadro de dolor abdominal en fosa iliaca derecha acompañado de vómito. Sin antecedentes prenatales ni natales de importancia. Al examen físico FC: 100/min, FR: 24/min, TA: 115/70 mmHg, temperatura: 38°C. El abdomen está suave, depresible, doloroso a la palpación en fosa iliaca derecha con reacción peritoneal a ese nivel. Se decide realizar laparoscopia diagnóstica encontrando apéndice cecal sin ninguna patología, pero a 60 cm de la válvula iliocecal presencia de un divertículo en la cara antimesentérica del íleon. ¿Cuál de los siguientes hallazgos se podría encontrar en el estudio histopatológico del divertículo?",
