    "stem": "Una mujer de 44 años acude al servicio de emergencias por cuadro de 5 días de evolución de importante lagrimeo del ojo derecho, acompañada de dolor en la región medial del párpado inferior. No ha notado pérdida de la visión. Sus antecedentes personales incluyen hipertensión arterial hace 5 años en tratamiento con amlodipina 10 mg/ día. Al examen físico FC: 95/min, FR: 19/min, TA: 115/75 mmHg, temperatura: 37 °C. El examen ocular agudeza visual normal en ambos ojos, isocoria, reactivas a la luz. En ojo derecho: presencia de epífora, inflamación periocular con elevación mínima en la zona interna del párpado inferior por debajo del tendón cantal interno. Se ejerce leve presión sobre la zona elevada y se observa salida de una secreción purulenta de color amarillento. El hemograma muestra leucocitos de 15000 /mm3 con 88% de segmentados neutrófilos. ¿Cuál es el diagnóstico más probable de la paciente?",
