    "stem": "Acude a su chequeo pre quirúrgico, una paciente femenina de 46 años que va a ser sometida a una histerectomía por presencia de múltiples miomas que le producen metrorragias con anemia de difícil manejo. No refiere antecedentes de importancia, viajes recientes, alergias o transfusiones. Al examen físico, la paciente se encuentra hemodinámicamente estable, conjuntivas pálidas, mucosas orales húmedas. Cardiopulmonar: ruidos rítmicos, no soplos, murmullo vesicular conservado, sin ruidos sobreañadidos. Abdomen: leve dolor a la palpación en hipogastrio. Se realiza su chequeo anestesiológico, y es autorizada realizarse su procedimiento quirúrgico. ¿Qué conducta en cuanto a profilaxis antibiótica tendría en este caso?",
