    "stem": "Varón de 10 meses consulta porque hace 3 días presentó fiebre durante 24 horas. Ese día vomitó dos veces. Desde entonces tiene tos, rinitis, conjuntivitis y deposiciones abundantes y acuosas, en número de 4-6 al día. No tiene sangre en las deposiciones, pero sí moco. La madre refiere que ha seguido dieta con leche al medio y alimentación astringente, con aporte de un vaso de SRO tras cada deposición suelta, sin notar mejoría. El niño asiste a guardería. Examen físico: peso: 9.800 g. (p50); talla: 73 cm. (p50). Buen estado general y de hidratación. Mucosas húmedas, masa muscular eutrófica. Afebril. Abdomen distendido, con timpanismo y borborigmos, no doloroso. Importante eritema en el área del pañal. Hiperemia orofaríngea y conjuntival. Resto de la exploración física es normal. ¿Cuál es la opción más adecuada para su diagnóstico?",
