    "stem": "Una Mujer de 30 años acude a consulta por presentar flujo vaginal de mal olor que se intensifica durante la relación sexual; niega síntomas irritativos, niega disuria. No tiene antecedentes personales de importancia. Vida sexual activa sin protección, 1 pareja sexual. Al examen físico de la región inguino genital: secreción grisácea en el vestíbulo vaginal, al examen especular paredes vaginales normales, flujo grisáceo homogéneo espumoso de mal olor, el cérvix tiene aspecto macroscópico normal. La medición del PH vaginal con papel de nitrazina es de 5. Al tacto vaginal: útero de tamaño y consistencia normal, no hay dolor a la lateralización cervical, los anexos no son palpables. Prueba de KOH positiva. El gram y fresco de secreción vaginal reporta la presencia de células clave. ¿Cuál de los siguientes es el agente infeccioso causal más probable?",
