    "stem": "Un hombre de 50 años es evaluado en la emergencia de un hospital a causa de dolor torácico retroesternal de 30 minutos de evolución. A primera vista se le ve ansioso, disneico, diaforético. Sus signos vitales evidencian una TA: 175/110 mmHg, FC: 110 lpm, FR: 30 x min, SatO2: 94 % al aire ambiente, corazón rítmico, sin soplos ni frotes, pulmones sin hallazgos pertinentes, pulsos distales sincrónicos y simétricos. Un ECG informa una elevación del ST en V2-V4. Inmediatamente se ordena administrar: aspirina masticada, oxígeno por catéter nasal a 2 lts/min, nitroglicerina sublingual y morfina IV. Sin embargo, el dolor no cede. ¿Qué acción terapéutica sería más apropiada para este paciente en este momento?",
