  {
    "id": "html-975",
    "subject": "Banco general de medicina",
    "stem": "Paciente femenina de 55 años acude por presentar ictericia de 2 días de evolución. Su cuadro se acompaña de astenia, adinamia de varios meses de evolución. Como antecedentes, refiere ser hipertensa, toma amlodipina 5 mg QD. Antecedentes quirúrgicos: histerectomía post parto hace 20 años, por lo que recibió transfusiones sanguíneas. Niega consumo de alcohol, tabaco, drogas o viajes recientes. Además indica prurito en miembros inferiores desde hace 3 semanas que empeora en las noches. Acudió dónde médico general que le indicó cremas humectantes y cetirizina sin mejoría del prurito. Al examen físico, los signos vitales están normales. Se evidencia ictericia escleral y sublingual. Cardiopulmonar: normal. Abdomen: blando, depresible, no doloroso a la palpación, ruidos presentes. A la percusión, el hígado mide 14 cm en línea medio clavicular derecha, abdomen timpánico. No esplenomegalia. No edema en miembros inferiores, se evidencian lesiones por rascado. Examen neurológico normal. ¿A qué podría deberse su ictericia?",
