    "stem": "Una mujer de 65 años acude a consulta médica por cuadro de dolor abdominal leve de 6 meses de evolución, acompañado de importante pérdida de peso, prurito generalizado y orina obscura. El dolor es leve y mal localizado. No ha presentado náuseas ni alteraciones defecatorias. Sus antecedentes personales incluyen pancreatitis crónica diagnosticada hace 5 años, última exacerbación hace 1 año. Al examen físico FC: 66/min, FR: 18/min, TA: 100/65mmHg, temperatura:36.5 °C, peso: 45 kg, talla: 1.6m. ictericia marcada en piel y mucosas, la piel presenta signos de rascado. La química sanguínea muestra creatinina 1 mg/dl, glucosa 119 mg/dl, TGO 3000 UI/L, TGP 450 UI/L, fosfatasa alcalina 340 UI/L, bilirrubina total 9.5 mg/dl, bilirrubina directa 7.1 mg/dl, bilirrubina indirecta 1.4 mg/dl. Considerando el diagnóstico probable de la paciente. ¿Cuál de los siguientes signos esperaría encontrar en el examen físico abdominal?",
