    "stem": "Un paciente de 2 años tiene desde hace 5 días heces acuosas con tolerancia de la vía oral, sin moco ni sangre, con una frecuencia de 4 a 5 por día. Al examen físico se lo encuentra irritable, con ojos hundidos, sediento y con un signo del pliegue negativo. Llenado capilar 2 segundos. ¿Cuál de estas opciones sería la mejor alternativa terapéutica?",
