    "stem": "Mujer de 33 años, arquitecta. Dos meses de evolución de dolor articular en muñecas, codos y tobillos. Hace 5 días nota edema, dolor, calor y enrojecimiento en el antebrazo izquierdo. Ha tenido dos abortos espontáneos previos alrededor de las 8 semanas de gestación. No hay historia familiar de trastornos similares. Los signos vitales están estables. En el examen físico se observa signos de trombosis venosa profunda en el miembro superior izquierdo; en las piernas hay un patrón reticular de decoloración rojiza y azulada de la piel. Hb 14 g/dl, Hcto 42%, plaquetas 98.000 mm3, TP 12 segundos, TTP 50 segundos, Leucocitos y formula diferencial normal. VSG 9mm /hora. Creatinina 0.9 mg/dl, VDRL reactivo, dilución 1:16; ANA positivo patrón homogéneo a título 1/160, Anti DNA de doble cadena negativo, Anti Ro Negativo. ¿Cuál es el diagnóstico más probable en esta paciente?",
