    "stem": "Un hombre de 75 años, diabético insulinodependiente, hipertenso y con antecedentes de angina de pecho y cirugía de carótida derecha hace 3 años por estenosis ateroesclerótica, consulta por dolor epigástrico posprandial de 30 minutos de duración que cede espontáneamente. El paciente ha reducido su ingesta alimentaria por temor al dolor y ha perdido el 15% de su peso corporal en tres meses por esta causa. Un médico le indicó antiácidos y procinéticos pero el cuadro no mejoró. Examen físico: TA: 150/95 mm Hg, FC: 80 lat/min, FR: 18 x min. Sat. O2: 92 %. No se realizan exámenes complementarios. ¿Cuál sería su diagnóstico presuntivo más probable?",
