    "subject": "Banco general de medicina",
    "stem": "Varón de 43 años. Hace 12 días tuvo drenaje quirúrgico por un hematoma subdural traumático frontal derecho. A los cinco días de la cirugía, inicia fiebre, cefalea holocraneana, intensa, vómito y disminución de la conciencia. La TA 140/80 mmHg, 96 LPM, 38.4 °C temperatura bucal, 91% saturación O2 (aire ambiente), desorientado en tiempo y espacio, fondo de ojo normal. Pupilas isocóricas de 2 mm de diámetro reactivas a la luz, no déficit motor. Rigidez de nuca y signo de Kernig. Leucocitos 15,610/mm3, 78% neutrófilos, PCR 14,3 mg/dl, procalcitonina 2,8 ng/ml, Na 140 mmol/L, K 4,7 mmol/L. La TAC cerebral simple revela estigmas craniectomía frontal derecha, no evidencia de hematoma subdural. La punción lumbar revela 3820 leucocitos/mm3, 82% neutrófilos, 65 mg/dl proteínas y glucosa 32 mg/dl (glucosa sérica 81 mg/dl). ¿Cuál es la bacteria más probable de la meningitis en este paciente?",
