    "stem": "Niña de 20 meses que pesa 10 kilogramos que desde hace 48 horas presenta fiebre de 38.9 °C acude a emergencia. Su estado general es bueno, no presenta manifestaciones tóxico infecciosas. Al examen físico la Frecuencia Cardíaca es de 102 X Min, SO2: 95% y la Frecuencia Respiratoria 32 X Min. Si bien la paciente presenta hiporexia, tolera bien el seno materno, come algo de alimentos sólidos y toma un poco de agua a libre demanda. ¿Cuál sería la conducta más apropiada para esta paciente?",
    "options": [
