    "stem": "Mujer de 60 años, acude al hospital por cefalea intensa de predominio temporal, que se presenta a diario desde hace aproximadamente 5 semanas, acompañada en la última semana de dolor mandibular al masticar y visión borrosa, sin causa aparente y sin antecedentes de importancia. A la exploración física se objetiva: TA: 118/80 mm Hg, FC: 110 lpm, temperatura axilar 37.6 °C, SatO2 aire ambiente 96 %, diplopía monocular derecha, claudicación de los músculos maseteros, dolor a la palpación en el cuero cabelludo de la zona temporal derecha sin presencia de lesiones; resto de la exploración sin alteraciones. Los estudios de laboratorio muestran anemia leve normocítica normocrómica, velocidad de sedimentación globular de 50 mm/hora. ¿Cuál es el diagnóstico más probable?",
