    "stem": "Paciente masculino de 4 años que acude a emergencias por diarrea y fiebre. Las diarreas son abundantes, no mucosanguinolentas, 12 en 24 horas. Ha presentado vómito por 6 ocasiones. Madre administró acetaminofén y probióticos. Sin embargo en las últimas 24 horas el paciente está somnoliento, decaído, no orina. Examen físico: llenado capilar 4 segundos, tensión arterial 65/40 mmHg, frecuencia cardiaca 180 /minuto, frecuencia respiratoria 50/minuto, temperatura axilar 36.8 °C, en mal estado general, letárgico, ojos hundidos, piel y mucosas orales secas, pulsos disminuidos, extremidades frías, signo de pliegue ++. ¿Cómo debe ser la hidratación inicial intravenosa?",
