    "stem": "Escolar de 7 años, presenta tos productiva con esputo café amarillento y fiebre desde hace 3 días. Tiene dolor en tórax posterior. Astenia y anorexia. T: 39,2 °C; FC: 116 x minuto; FR: 44 x minuto. SO2 = 86%. Se auscultan estertores finos en la base derecha. La Rx demuestra consolidación del parénquima pulmonar en la base derecha. ¿Cuál es el germen causante más probable y el tratamiento correspondiente?",
