    "id": "html-1054",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 35 años solicita consulta con un médico, a causa de episodios súbitos de ansiedad intensa que han ocurrido desde aproximadamente tres semanas atrás. Los episodios son ocasionales. Entre las crisis, ella “está muy pendiente y preocupada de cuándo ocurrirá el próximo ataque de nervios” (en sus propias palabras). Al ser interrogada, no puede identificar un factor desencadenante ni ninguna situación causal de estos episodios, tampoco encuentra ninguna relación con eventos en particular o alguna hora del día. Se la explora físicamente y no se identifica ningún hallazgo anormal, excepto que está bastante agitada. Sin embargo, el médico aconseja a la paciente consultar con un psiquiatra. Mientras tanto, decide iniciar tratamiento. De las siguientes alternativas de terapia, ¿cuál no estaría recomendada para esta paciente?",
