    "stem": "Hombre de 22 años, acude a consulta por tos con expectoración, malestar general y disnea de 3 días de evolución. Antecedentes personales: ninguno. Examen físico: TA: 120/80 mmHg, FC: 89 lpm, FR: 28 rpm, Saturación: 89% aire ambiente (2850m). Pulmonar: a la auscultación de base pulmonar izquierda se evidencia murmullo vesicular más estertores crepitantes. Resto de examen normal. En estudio de imagen: radiografía de tórax posteroanterior se observa opacidad en lóbulo inferior izquierdo hacia el ángulo costofrénico. ¿Cuál de los siguientes patrones radiográficos es más probable que revele la radiografía del paciente?",
