    "stem": "Paciente de 17 años, con embarazo de 35 semanas, refiere que desde hace 3 días presenta dolor costo lumbar intenso, disuria y polaquiuria. A la exploración física: Consciente y orientada auto y alopsíquicamente. Temperatura: 38 °C, presión arterial 105/60, frecuencia cardiaca 110 por minuto, frecuencia respiratoria de 20 por minuto, saturación de O2 95%. Diuresis horaria 30 ml / hora, en este caso. ¿Cuál es el valor del Quick SOFA?",
