    "stem": "Varón de 71 años acude a urgencias por fiebre de 39°C y cefalea de 36 horas de evolución. Antecedentes: bronquitis crónica en tratamiento con corticoides desde hace 8 meses y alcoholismo. Al examen físico paciente consciente y orientado en las tres esferas con Glasgow 15/15. Los signos vitales son: TA: 125/75 mmHg, FC: 120 lpm, FR: 14 rpm, T: 38°C, SpO2 96%. Rigidez de nuca con signo de Kernig positivo y fondo de ojo normal. Resto de la exploración normal. En la punción lumbar se obtiene LCR (líquido cefalorraquídeo) de aspecto normal. El estudio microbiológico reporta en la tinción Gram del LCR predominio de polimorfonucleares y abundantes bacilos Gram positivos. ¿Cuál es el microorganismo causal más probable del cuadro que presenta el paciente?",
