  {
    "id": "html-1111",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 41 años, multípara con 5 partos vaginales. Acude desde hace 2 días por dolor intenso en la zona inguinal derecha, acompañado de náuseas y vómitos. No fiebre. Desde hace 2 años que presenta bulto inguinal derecho que sobresale cuando realiza esfuerzos físicos y luego regresaba a su sitio sin problemas. A la exploración se objetiva masa con saco herniario irreductible localizado por debajo del ligamento inguinal derecho de aproximadamente 3 cm de diámetro mayor, dolorosa a la digitopresión, Mc Burney negativo, sin signos de irritación peritoneal. La ecografía evidencia defecto de la pared abdominal posterior tipo III C, sin compromiso vascular. ¿Cuál es la patología de la paciente?",
