  {
    "id": "html-1112",
    "subject": "Banco general de medicina",
    "stem": "Varón de 25 años, evaluado en urgencias por contacto con líquido hirviendo en brazo derecho. Refiere dolor 7/10 del área afectada. Niega antecedentes médicos de importancia. Alergias no conocidas. Al examen físico: tensión arterial 140/90 mmHg, frecuencia cardíaca 104 latidos por minuto, frecuencia respiratoria 18 por minuto, oximetría de pulso 90 % al aire ambiente. Brazo derecho: lesión que involucra epidermis, dermis y hasta grasa subcutánea, con extensión aproximada de 3 cm x 5cm, bordes irregulares, sin flictenas. ¿Qué tipo de quemadura presenta el paciente?",
