  {
    "id": "html-1113",
    "subject": "Banco general de medicina",
    "stem": "Un paciente de 3 años, sin su esquema de vacunas completo, presenta rinitis de 7 semanas de evolución, acompañada desde hace 4 días de fiebre, tos productiva, taquipnea y dificultad respiratoria. Se auscultan estertores diseminados y roncus en la base derecha. El diagnóstico probable es Neumonía. ¿Cuál es el medicamento recomendado para este caso?",
