  {
    "id": "html-1114",
    "subject": "Banco general de medicina",
    "stem": "Varón de 66 años, desde hace 5 días presenta disuria, urgencia urinaria, dolor en el hipogastrio y alza térmica. No reporta hematuria, ni dolor lumbar. El paciente tiene una prótesis valvular mecánica mitral desde hace 20 años, se encuentra en tratamiento con Warfarina sódica y el último control de INR fue hace una semana, con un valor de 2.9. Hace 18 meses presentó un infarto en el territorio de la arteria cerebral media derecha que dejó como secuela una hemiparesia izquierda espástica, requiriendo de asistencia para la marcha. Tiene antecedentes hace dos años de un sangrado digestivo alto secundario al uso de la Warfarina. La biometría es normal. INR 2.8; EMO piocitos 15 por campo; bacterias +++. Cultivo: E. coli. ¿Cuál es el antibiótico que debe ser administrado en el paciente?",
