    "id": "html-1115",
    "subject": "Banco general de medicina",
    "stem": "Varón de 61 años acude a consulta externa para evaluación preoperatoria por hernia umbilical. Antecedente de cirrosis hepática en tratamiento clínico con espironolactona. Niega hábitos tabáquico y alcohólico actual. Asintomático. No datos de encefalopatía. Examen físico: Tensión arterial 140/90 mmHg, frecuencia cardíaca 104 latidos por minuto, frecuencia respiratoria 24 por minuto, IMC 28 Kg/m2. Abdomen: No evidencia ascitis, hernia umbilidal reducible. Telangiectasias periféricas. Laboratorio: Bilirrubina 3.2 mg/dL, Albumina 3,6 g/L, Tiempo de protrombina: 15 segundos. INR 1.2. ¿Cuál es el factor que predice el mayor riesgo quirúrgico en este paciente?",
