  {
    "id": "html-1116",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 25 años, médica, acude a su chequeo clínico anual. Al momento de la evaluación la paciente se encuentra asintomática. El test cutáneo para tuberculosis (PPD, TST) produce una reacción de 12 mm en 48 horas. Se realiza una radiografía de tórax que no muestra lesiones pulmonares. Se considera que la paciente tiene tuberculosis latente y se decide iniciar tratamiento con Rifampicina. Al cabo de 17 días presenta fiebre, dolor articular, una erupción cutánea de tipo exantemática en tórax y abdomen, además de elevación sérica de creatinina y nitrógeno ureico (BUN). La biometría hemática muestra leucocitosis con eosinofilia. En el análisis microscópico de orina no se observan eritrocitos ni bacterias, sin embargo, se identifica cilindros leucocitarios compuestos por eosinófilos. Dados los antecedentes, síntomas, signos y hallazgos de laboratorio, ¿cuál es el diagnóstico más probable en esta paciente?",
    "options": [
      "Nefritis intersticial aguda",
      "Pielonefritis por Mycobacterium tuberculosis",
