    "stem": "Se trata de un protozoario que puede producir diarrea aguda o persistente, algunas veces malabsorción con esteatorrea, dolor abdominal y sensación de saciedad. Sin embargo, la gran mayoría de las infecciones son asintomáticas. Tiene distribución mundial, la prevalencia de la infección entre los niños pequeños alcanza 100 % en algunas áreas. Los niños entre 1 a 5 años son los más infectados. Estas son características del agente etiológico de la diarrea conocido como:",
