    "stem": "Mujer de 26 años acude a urgencias con labor de parto refiriendo \"ruptura de agua de fuente\". Cumplió 12 consultas prenatales sin evidenciar complicación. Niega antecedentes médicos de importancia. Gestas 2, Parto 1, Aborto 0. Embarazo actual de 40 semanas por fecha de última menstruación. Al examen físico presenta tensión arterial 120/80 mmHg, frecuencia cardíaca 74 latidos por minuto, frecuencia respiratoria 16 por minuto. Abdomen: suave, depresible, no doloroso. Fondo uterino acorde a edad gestacional. Feto único, cefálico. Frecuencia cardíaca fetal: 156 latidos por minuto. Tacto vaginal: dilatado 2 cm, borrado 50 %. Actividad uterina 1 en 10 minutos repetida en 1 hora. Laboratorio: cristalografía positiva. ¿Qué fármaco es el más indicado para el manejo inicial de esta paciente?",
