  {
    "id": "html-1130",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 68 años, acude a emergencia por dolor en epigastrio irradiado a fosa ilíaca derecha, náuseas, vómitos de contenido gástrico y fiebre de 3 días de evolución. Niega antecedentes personales. Examen físico: TA: 70/40 mmHg, TAM: 53 mmHg, FC: 122 lpm, FR: 24 rpm, T: 39°C, Saturación: 88% aire ambiente (2850m), Glasgow: 13/15 (O:3, V:4 M:6) Paciente somnolienta, piel pálida fría. Abdomen: ruidos hidroaéreos disminuidos, poco depresible, doloroso a la palpación en fosa ilíaca derecha, signos de Blumberg positivo. Extremidades: pulso débil filiforme, llenado capilar 5 seg. Escalas pronósticas: qSOFA 3 puntos. En complementarios se evidencia: Leucocitos 21000 /mm3, Hb 11 g/dl, Hto 33%, Plaquetas 120.000, Creatinina 1,1 mg/dl, Urea 45 mg/dl, Gasometría arterial: Ph: 7,30 PCO2: 35 mmHg, PO2: 60 mmHg, HCO3: 15 mEq/L, Lactato 5 mg/dl. Se administró cristaloides intravenosos a 30 mL/kg en bolo por 2 ocasiones, con lo cual se obtiene TAM 55 mmHg. ¿Cuál es el próximo paso más adecuado para el manejo?",
