  {
    "id": "html-1131",
    "subject": "Banco general de medicina",
    "stem": "Una mujer de 45 años es evaluada por dolor en la región anterior de su cuello, de dos semanas de evolución, continuo, intensidad 10/10, agudo. Se ha acompañado de deposiciones blandas y astenia generalizada. Su historia médica da cuenta de una HTA que es tratada con un IECA-hidroclorotiazida. Hace un mes cursó con un cuadro respiratorio que duró pocos días. Al examen físico se aprecia una TA: 138/80 mm Hg, FC: 96 lpm, FR: 16 x min, Temp: 38 °C. Al palpar su tiroides se nota un crecimiento difuso de la glándula, la cual es muy dolorosa. La paciente evita la palpación. Se solicitaron exámenes complementarios cuyos resultados son: T3: incrementada ng/dl, T4: incrementada, TSH: disminuida. ¿Cuál de los siguientes sería el diagnóstico más probable?",
