  {
    "id": "html-1133",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 23 años acude a consulta prenatal con aumento de secreción vaginal. Niega antecedentes personales y familiares de relevancia. Gestas 2, Parto 1, Aborto 0. Embarazo actual de 24 semanas. Al examen físico se evalúa con signos vitales normales. Abdomen: suave, depresible, no doloroso. Fondo uterino acorde a edad gestacional. Se coloca espejo vaginal y se observa una cervicitis mucopurulenta sin olor. El examen en fresco es negativo. La tinción de Gram no identifica gérmenes. El cultivo de la secreción reporta una bacteria intracelular obligada y una prueba de amplificación de ácidos nucleicos negativo para Neisseria gonorrhoeae. ¿Qué tratamiento de una sola dosis es el más apropiado en este caso?",
