  {
    "id": "html-1135",
    "subject": "Banco general de medicina",
    "stem": "Un hombre de 60 años es evaluado en el servicio de emergencia a causa de tos de inicio súbito, con expectoración amarillenta y disnea. Tiene antecedente de HTA y se trata con Amlodipino. Al examen físico está tiene una Temp. 38.9 °C, FR: 20 x min, SatO2: 91 %; se auscultan estertores en lóbulo superior derecho y movilización de secreciones, MV conservado en ápice pulmonar derecho, no frotes, la percusión es normal. No hay broncofonía. Se le realiza una Rx de tórax que muestra un infiltrado alveolar en el lóbulo superior derecho. Los resultados de exámenes de laboratorio son: BUN: 53 mg /dl, creatinina: 2.8 mg/dl, calcio: 12.3 mg/dl, proteínas totales: 9 g/dl y albúmina de 3.1 g/dl. Se realiza un cultivo de esputo y se aisla Streptococcus pneumoniae. ¿Cuál es el siguiente examen que se debería realizar para confirmar la condición subyacente que predispone a este paciente a tener este cuadro clínico?",
