    "subject": "Banco general de medicina",
    "stem": "Paciente femenina de 28 años, antecedente de madre diabética, es diagnosticada de colecistolitiasis por cólico biliar a repetición. Se programa colecistectomía laparoscópica; en el transoperatorio se perfora la vesícula accidentalmente con escape notable de bilis y litos hacia la cavidad peritoneal. El cirujano realiza lavado de la cavidad y extracción de todos los litos. ¿Cuál sería el procedimiento adecuado para disminuir la infección del sitio operatorio o sitio quirúrgico?",
