    "stem": "Una niña de 3 años presenta una erupción exantemática máculo-papulosa con lesiones redondeadas de color rojo en la cara (mejillas y área peribucal) que después se han diseminado hacia el tronco y las extremidades y que han desaparecido sin descamación luego de tres días. Presenta adenopatías occipitales, retroauriculares y cervicales. Su madre indica que hace 2 semanas su hija estuvo en una guardería jugando con otros niños de su edad. ¿Cuál es el diagnóstico más probable?",
