    "stem": "Hombre de 80 años es llevado a emergencias por dolor abdominal intenso y difuso de 16 horas de evolución que se acompaña de numerosas diarreas vinosas. Antecedentes patológicos: fibrilación auricular crónica con abandono del tratamiento desde hace 1 mes. Al examen físico presenta: FC: 100/min, FR: 20/min, TA: 90/60 mmHg, temperatura: 36°C. Corazón: ruidos cardiacos arrítmicos, no soplos. Abdomen: ruidos hidroaéreos ausentes, suave, depresible, dolor muy intenso de forma difusa, sin defensa muscular ni signos de irritación peritoneal. Prueba del guayaco en heces: negativa. ¿Cuál es la causa más común del cuadro que presenta el paciente?",
