  {
    "id": "html-1142",
    "subject": "Banco general de medicina",
    "stem": "Se trata de un protozoario de distribución mundial y prevalencia muy variable. La incidencia aumenta con la edad y es mayor en los hombres adultos. Al menos 90% de las infecciones producidas por este agente son asintomáticas, causadas por cepas que no deberían ser tratadas. Es causa poco frecuente de disentería en niños. El diagnóstico de enfermedad invasiva requiere la identificación de trofozoítos hematófagos en las heces o en las ulceras del colon. Puede producir desde diarrea persistente moderada hasta disentería fulminante o absceso hepático. Estas son características del agente etiológico de la diarrea conocido como:",
