    "stem": "Un hombre de 55 años acude a consulta médica por presentar episodios repetidos de ataques de asma. Sus antecedentes personales incluyen asma desde la infancia agravados desde hace 3 meses, los ha controlado con sus inhaladores habituales, presenta desde ese mismo tiempo hipertensión arterial diagnosticada, no recuerda la medicación que está tomando. Al examen físico TA: 130/85 mmHg, FC: 55/min, FR: 18/min, temperatura: 37 °C. pulmones con murmullo vesicular conservado, no se auscultan sibilancias al momento. Se cuantifica electrolitos en sangre: Na 140 mEq/l, K 4.3 mEq/l y Cl 109 mEq/l. ¿Qué tratamiento antihipertensivo es más probable que esté recibiendo el paciente?",
