    "stem": "Paciente masculino con deterioro del estado general, acude con fiebre, fatiga, taquicardia. Laboratorio: VIH+. RX de tórax: cavidad aérea de 11x 4 cm. Familiares realizan una reclamación judicial posterior al fallecimiento en emergencia. ¿En qué condición se vulnera la confidencialidad de datos?",
