    "stem": "Escoja la opción que tiene todos los pilares fundamentales de la relación médico paciente según el código Deontológico capítulo III (art 3 al 7). 1. Respeto. 2. Continuidad en la relación. 3. Confianza mutua. 4. Libre Elección. 5. Empatía. 6. Compromiso.",
