  {
    "id": "html-1185",
    "subject": "Banco general de medicina",
    "stem": "Una persona firmó el consentimiento informado, cumpliendo con todos los requerimientos establecidos para un procedimiento quirúrgico. Antes de la cirugía el paciente decide no realizarse la operación. Seleccione la conducta apropiada:",
