  {
    "id": "html-1186",
    "subject": "Banco general de medicina",
    "stem": "Un grupo de investigación de un hospital realizará un ensayo clínico controlado. El Comité de Bioética debidamente legalizado autorizó la investigación. La institución proveerá de los fondos necesarios para ejecutarla. Los pacientes participantes firmarán el consentimiento informado. Seleccione la opción correcta en relación a la responsabilidad de la confidencialidad de los datos de los pacientes:",
