    "fixedOrder": false
  },
  {
    "id": "html-1187",
    "subject": "Banco general de medicina",
    "stem": "Los familiares de un enfermo grave, incapacitado para decidir el curso de su tratamiento, presentan al médico tratante el testamento vital del paciente. Según este documento, pide a los médicos que en caso de que su condición no sea recuperable en términos de calidad de vida, únicamente se le administren los medicamentos necesarios para evitar mayores sufrimientos, pero en ningún caso para prolongar su vida artificialmente. Seleccione la opción correcta en relación a la ejecución de este testamento vital, si luego de otra opinión autorizada, no existen posibilidades de una sobrevida adecuada:",
    "options": [
      "El médico debe cumplir con la voluntad del paciente.",
      "Una junta de médicos debe decidir su posible cumplimiento.",
