  {
    "id": "html-1195",
    "subject": "Banco general de medicina",
    "stem": "Un médico residente, atiende en urgencias a una paciente de 19 años que ha sufrido una pérdida de conciencia transitoria en la Universidad, mientras esperaba muy angustiada el momento de rendir un examen. Los signos vitales y la exploración física son normales. La paciente se mantiene en observación a la espera de los resultados de los exámenes de laboratorio y de imagen realizados. En un momento determinado, el médico residente encuentra a la paciente chateando con su teléfono celular. El médico le sugiere que es mejor que descanse y le comenta que a él también le agradan las redes sociales; entonces la paciente le pregunta si podrá hacerle una solicitud de amistad en Facebook por si se sintiera angustiada y necesitará comunicarse con el médico. ¿Cuál es la conducta más adecuada del médico frente a esta solicitud?",
    "options": [
      "Indicarle que no haga la solicitud, manifestándole que es importante mantener ciertos límites profesionales entre la paciente y el médico.",
      "Decirle que haga la solicitud de amistad, que la aceptará y que le responderá a cualquier consulta.",
      "Acepta la solicitud de amistad ya que no quiere que la paciente puede interpretar mal un rechazo.",
      "Decirle que haga la solicitud de amistad, pero el médico no tiene intención de aceptarla."
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 1195 · pág. 454",
    "fixedOrder": false
  },
  {
    "id": "html-1196",
    "subject": "Banco general de medicina",
    "stem": "Paciente masculino de 48 años, acude a consulta para un control preventivo. El paciente es un fumador de 10 tabacos al día desde hace 30 años. La TAC de tórax muestra leves signos de enfisema centrolobulillar. Usted recomienda al paciente que debe suspender completamente el hábito tabáquico para disminuir el riesgo de complicaciones posteriores incluyendo el cáncer de pulmón. Entonces, el paciente solicita que usted le prescriba antioxidantes para prevenir el cáncer del pulmón, puesto que de acuerdo al paciente es bien conocido que los antioxidantes previenen el desarrollo del cáncer en varios órganos. Usted conoce que no hay ninguna evidencia sólida en este sentido y que al contrario hay datos que sugieren que algunos antioxidantes podrían incrementar el riesgo de cáncer de pulmón. ¿Cuál es la conducta más apropiada en este caso?",
    "options": [
      "Explicar al paciente la evidencia disponible y negarse a prescribir el tratamiento.",
      "Explicar al paciente la evidencia disponible y prescribir un antioxidante si hay insistencia del paciente.",
      "Indicarle al paciente que usted no va a prescribir una sustancia que no tiene evidencia y que usted no puede ser su médico tratante.",
      "Explicarle al paciente que no hay evidencia sólida, solicitarle que firme un"
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 1196 · pág. 454",
    "fixedOrder": false
  },
  {
    "id": "html-1197",
    "subject": "Banco general de medicina",
    "stem": "Varón de 23 años acude a consulta particular de dermatología por problemas de acné. Refiere que lleva varios años con distintos tratamientos pero no ha obtenido el resultado esperado. No refiere antecedentes de importancia. Al examen físico los signos vitales son normales y se objetivan varias lesiones nódulo – quísticas en cara, cuello y espalda. Al considerar un cuadro crónico y refractario el especialista decide empezar tratamiento con isotretinoína. Se le informa al paciente que la isotretinoína empeora las lesiones durante las primeras semanas, según lo expuesto. ¿Qué información se está explicando al paciente?",
    "options": [
      "Efectos adversos.",
      "Descripción del tratamiento.",
      "Alternativas disponibles.",
      "Recomendaciones del médico."
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 1197 · pág. 455",
    "fixedOrder": false
  },
  {
    "id": "html-1198",
    "subject": "Banco general de medicina",
    "stem": "Mujer de 25 años, acude a emergencias de una clínica privada por odinofagia y alza térmica no cuantificada de 2 días de evolución. No tiene antecedentes importantes. Al examen físico presenta signos vitales normales. ORF: discreto eritema en pared posterior faríngea, sin placas ni exudados. Resto de la exploración normal. El médico que valora a la paciente, solicita exámenes con el fin de hospitalizarla y obtener un beneficio económico. Los exámenes son normales, pero le dice a la paciente que están alterados y que necesita ser hospitalizada. Con esta información, la paciente siente temor y acepta el ingreso. ¿Qué tipo de mecanismo utiliza el médico para influir en la decisión de la paciente?",
    "options": [
      "Manipulación informacional.",
      "Persuasión.",
      "Manipulación psicológica.",
      "Amenaza psicológica."
    ],
    "key": 0,
    "source": "Banco educativo EstudiaMed · pregunta 1198 · pág. 455",
    "fixedOrder": false
  },
  {
    "id": "html-1199",
    "subject": "Banco general de medicina",
    "stem": "El Hospital Judío de Enfermedades Crónicas (Jewish Chronic Disease Hospital), inoculó células cancerosas a pacientes ancianos sin su consentimiento. Este experimento se lo hizo bajo la hipótesis de que dichas células serían rechazadas. La falta de consentimiento. ¿Qué principio bioético quebrantó?",
