    "stem": "Lactante de tres meses con malformación cerebral congénita, escafocefalia e hidrocefalia. Se halla con diagnóstico presuntivo de meningoencefalitis. El médico tratante ha sugerido un procedimiento invasivo para obtener líquido céfalo raquídeo. Los padres del lactante son mayores de edad en unión estable, ambos con educación superior. ¿Quién debe firmar el consentimiento informado escrito para autorizar este procedimiento?",
